import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Container,
  Paper,
  Typography,
  Box,
  Button,
  Grid,
  Chip,
  CircularProgress,
  Alert,
  IconButton,
  Card,
  CardContent
} from '@mui/material';
import {
  ArrowBack,
  Edit,
  Delete,
  Warning,
  CheckCircle,
  Store,
  LocalOffer,
  TrendingUp,
  AccessTime
} from '@mui/icons-material';
import { getProductById } from '../../services/products';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        setLoading(true);
        const response = await getProductById(id);
        const productData = response.data || response;
        setProduct(productData);
      } catch (error) {
        console.error('Erro ao carregar produto:', error);
        setError('Produto não encontrado ou erro ao carregar dados.');
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchProduct();
    }
  }, [id]);

  const handleBack = () => {
    navigate('/products');
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  const formatDate = (dateString) => {
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(new Date(dateString));
  };

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
          <CircularProgress />
        </Box>
      </Container>
    );
  }

  if (error || !product) {
    return (
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Alert severity="error" sx={{ mb: 2 }}>
          {error || 'Produto não encontrado'}
        </Alert>
        <Button
          variant="outlined"
          startIcon={<ArrowBack />}
          onClick={handleBack}
        >
          Voltar para Produtos
        </Button>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      {/* Cabeçalho */}
      <Box sx={{ mb: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <IconButton onClick={handleBack}>
            <ArrowBack />
          </IconButton>
          <Typography variant="h4" component="h1" fontWeight="bold">
            Detalhes do Produto
          </Typography>
        </Box>
      </Box>

      <Grid container spacing={3}>
        {/* Informações Principais */}
        <Grid item xs={12} md={8}>
          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h5" gutterBottom fontWeight="bold">
              {product.name || 'Nome não disponível'}
            </Typography>

            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 3 }}>
              <Chip
                label={product.category ? product.category.charAt(0).toUpperCase() + product.category.slice(1) : 'Categoria não definida'}
                color="primary"
                variant="outlined"
              />
              {product.status === 'active' ? (
                <Chip
                  label="Ativo"
                  color="success"
                  icon={<CheckCircle />}
                />
              ) : (
                <Chip
                  label="Inativo"
                  color="default"
                />
              )}
              {product.authorized && (
                <Chip
                  label="Oficial"
                  color="info"
                  variant="outlined"
                />
              )}
            </Box>

            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <Typography variant="body2" color="text.secondary">
                  Código do Produto
                </Typography>
                <Typography variant="body1" fontFamily="monospace" fontWeight="medium">
                  {product.code || 'Não informado'}
                </Typography>
              </Grid>

              <Grid item xs={12} sm={6}>
                <Typography variant="body2" color="text.secondary">
                  Vendedor
                </Typography>
                <Typography variant="body1">
                  {product.seller || 'Não informado'}
                </Typography>
              </Grid>
            </Grid>
          </Paper>

          {/* Histórico de Preços */}
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>
              <TrendingUp sx={{ mr: 1, verticalAlign: 'middle' }} />
              Informações de Preço
            </Typography>

            <Grid container spacing={2}>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Preço Atual
                </Typography>
                <Typography variant="h6" color="primary" fontWeight="bold">
                  {formatCurrency(product.currentPrice || 0)}
                </Typography>
              </Grid>

              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Preço de Referência
                </Typography>
                <Typography variant="h6">
                  {formatCurrency(product.referencePrice || 0)}
                </Typography>
              </Grid>

              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Variação
                </Typography>
                <Typography
                  variant="h6"
                  color={
                    (product.priceVariation || 0) > 0 ? 'error.main' :
                    (product.priceVariation || 0) < 0 ? 'success.main' : 'text.secondary'
                  }
                  fontWeight="bold"
                >
                  {product.priceVariation !== undefined
                    ? `${product.priceVariation > 0 ? '+' : ''}${product.priceVariation.toFixed(2)}%`
                    : 'Sem alteração'
                  }
                </Typography>
              </Grid>
            </Grid>
          </Paper>
        </Grid>

        {/* Sidebar com Informações Adicionais */}
        <Grid item xs={12} md={4}>
          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>
              <AccessTime sx={{ mr: 1, verticalAlign: 'middle' }} />
              Informações Temporais
            </Typography>

            <Box sx={{ mb: 2 }}>
              <Typography variant="body2" color="text.secondary">
                Criado em
              </Typography>
              <Typography variant="body1">
                {product.createdAt ? formatDate(product.createdAt) : 'Não disponível'}
              </Typography>
            </Box>

            <Box>
              <Typography variant="body2" color="text.secondary">
                Última Atualização
              </Typography>
              <Typography variant="body1">
                {product.lastUpdate ? formatDate(product.lastUpdate) : 'Não disponível'}
              </Typography>
            </Box>
          </Paper>

          {/* Card de Status */}
          <Card sx={{ mb: 3 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Status do Monitoramento
              </Typography>

              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                {product.status === 'active' ? (
                  <>
                    <CheckCircle color="success" sx={{ mr: 1 }} />
                    <Typography color="success.main">
                      Monitoramento Ativo
                    </Typography>
                  </>
                ) : (
                  <>
                    <Warning color="warning" sx={{ mr: 1 }} />
                    <Typography color="warning.main">
                      Monitoramento Pausado
                    </Typography>
                  </>
                )}
              </Box>

              <Typography variant="body2" color="text.secondary">
                {product.status === 'active'
                  ? 'Este produto está sendo monitorado ativamente para mudanças de preço.'
                  : 'Este produto não está sendo monitorado no momento.'
                }
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Container>
  );
};

export default ProductDetail;
