import { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  CircularProgress,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Card,
  CardContent,
  Alert,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Tabs,
  Tab,
  Grid,
  Chip
} from '@mui/material';
import {
  LightbulbOutlined as LightbulbIcon,
  BarChart as BarChartIcon,
  Refresh as RefreshIcon,
  Send as SendIcon,
  Psychology as PsychologyIcon
} from '@mui/icons-material';

const DataAnalysisAI = ({ analysisData }) => {
  const [loading, setLoading] = useState(false);
  const [question, setQuestion] = useState('');
  const [aiAnalysis, setAiAnalysis] = useState('');
  const [insights, setInsights] = useState([]);
  const [recommendationsMetric, setRecommendationsMetric] = useState('sales');
  const [recommendations, setRecommendations] = useState([]);
  const [error, setError] = useState(null);
  const [activeSection, setActiveSection] = useState('insights'); // 'insights', 'analysis', 'recommendations'

  // Funções utilitárias para derivar conteúdos reais a partir do analysisData
  const deriveInsights = (data) => {
    if (!data) return [];
    const out = [];

    // Insight 1: Estatísticas de preço
    if (data.priceStats) {
      out.push({
        title: 'Preço médio do mercado',
        description: `Preço médio: R$ ${Number(data.priceStats.avgPrice || 0).toFixed(2)} (mín: R$ ${Number(data.priceStats.minPrice || 0).toFixed(2)} | máx: R$ ${Number(data.priceStats.maxPrice || 0).toFixed(2)})`,
        importance: 0.85
      });
    }

    // Insight 2: Vendedor com melhor reputação
    if (Array.isArray(data.sellerPerformance) && data.sellerPerformance.length > 0) {
      const best = [...data.sellerPerformance].sort((a,b) => (b.reputation||0) - (a.reputation||0))[0];
      if (best) {
        out.push({
          title: 'Vendedor com melhor reputação',
          description: `${best.name} (${Number(best.reputation||0).toFixed(1)}★, ${best.products||0} produtos, preço médio R$ ${Number(best.avgPrice||0).toFixed(2)})`,
          importance: 0.8
        });
      }
    }

    // 🔧 CORRIGIDO: Insight 3: Termo de busca mais usado (a partir de searchTermsData)
    if (Array.isArray(data.searchTermsData) && data.searchTermsData.length > 0) {
      const topTerm = [...data.searchTermsData].sort((a,b) => (b.count||0) - (a.count||0))[0];
      if (topTerm) {
        out.push({
          title: 'Termo de busca mais popular',
          description: `${topTerm.term} (${topTerm.count} buscas realizadas)`,
          importance: 0.75
        });
      }
    }

    // Insight 4: Total de produtos
    if (typeof data.totalProducts === 'number') {
      out.push({
        title: 'Total de produtos analisados',
        description: `${data.totalProducts} itens no período selecionado`,
        importance: 0.7
      });
    }

    return out;
  };

  const deriveAnalysisText = (data, q) => {
    if (!data) return '';
    const lines = [];
    lines.push('## Análise baseada nos dados reais coletados');

    if (q) {
      lines.push(`Pergunta: "${q}"`);
    }

    if (data.priceStats) {
      lines.push(`- Preço médio: R$ ${Number(data.priceStats.avgPrice||0).toFixed(2)} (mín: R$ ${Number(data.priceStats.minPrice||0).toFixed(2)} | máx: R$ ${Number(data.priceStats.maxPrice||0).toFixed(2)})`);
    }
    if (data.vendorStats) {
      lines.push(`- Vendedores únicos: ${data.vendorStats.count||0}`);
    }
    if (typeof data.totalProducts === 'number') {
      lines.push(`- Total de produtos analisados: ${data.totalProducts}`);
    }

    if (Array.isArray(data.sellerPerformance) && data.sellerPerformance.length > 0) {
      const best = [...data.sellerPerformance].sort((a,b) => (b.reputation||0) - (a.reputation||0))[0];
      if (best) {
        lines.push(`- Melhor vendedor: ${best.name} (${Number(best.reputation||0).toFixed(1)}★ | preço médio R$ ${Number(best.avgPrice||0).toFixed(2)})`);
      }
    }

    // 🔧 CORRIGIDO: Usar searchTermsData em vez de priceRatingData
    if (Array.isArray(data.searchTermsData) && data.searchTermsData.length > 0) {
      const topTerm = [...data.searchTermsData].sort((a,b) => (b.count||0) - (a.count||0))[0];
      if (topTerm) {
        lines.push(`- Termo de busca mais popular: ${topTerm.term} (${topTerm.count} buscas realizadas)`);
      }
    }

    return lines.join('\n');
  };

  const deriveRecommendations = (data, metric) => {
    if (!data) return [];
    const recs = [];

    if (metric === 'sales') {
      // Se existir vendedor com alta reputação e preço acima da média
      if (Array.isArray(data.sellerPerformance) && data.priceStats) {
        const avg = data.priceStats.avgPrice || 0;
        const pricey = data.sellerPerformance.filter(v => (v.avgPrice||0) > avg);
        if (pricey.length > 0) {
          recs.push({
            title: 'Rever preços de vendedores acima da média',
            description: `Identificamos ${pricey.length} vendedor(es) com preço médio acima de R$ ${avg.toFixed(2)}. Avalie ajustes para aumentar a conversão.`,
            impact: 0.8,
            effort: 0.5,
            category: 'pricing'
          });
        }
      }
      // 🔧 CORRIGIDO: Usar searchTermsData em vez de priceRatingData
      if (Array.isArray(data.searchTermsData) && data.searchTermsData.length > 0) {
        const lowCountTerms = data.searchTermsData.filter(t => (t.count||0) < 10);
        if (lowCountTerms.length > 0) {
          recs.push({
            title: 'Termos de busca com poucos resultados',
            description: `${lowCountTerms.length} termo(s) de busca com menos de 10 resultados. Considere expandir a busca ou ajustar os termos.`,
            impact: 0.75,
            effort: 0.4,
            category: 'search'
          });
        }
      }
    }

    if (metric === 'price') {
      if (data.priceStats) {
        recs.push({
          title: 'Ajuste fino de preços',
          description: `Considerar ajustes em torno de ±5% do preço médio (R$ ${Number(data.priceStats.avgPrice||0).toFixed(2)}) para otimização de conversão.`,
          impact: 0.7,
          effort: 0.3,
          category: 'pricing'
        });
      }
    }

    if (metric === 'reputation') {
      if (Array.isArray(data.sellerPerformance)) {
        const mid = data.sellerPerformance.filter(v => (v.reputation||0) >= 3.5 && (v.reputation||0) < 4.2);
        if (mid.length > 0) {
          recs.push({
            title: 'Elevar reputação de vendedores medianos',
            description: `${mid.length} vendedor(es) com reputação entre 3.5★ e 4.2★ — treinar respostas rápidas e pós-venda pode elevar avaliações.`,
            impact: 0.65,
            effort: 0.4,
            category: 'customer_service'
          });
        }
      }
    }

    return recs;
  };

  // Atualiza visão ao receber dados reais
  useEffect(() => {
    if (!analysisData) return;
    try {
      const ins = deriveInsights(analysisData);
      setInsights(ins);
      setAiAnalysis(deriveAnalysisText(analysisData, question));
      setRecommendations(deriveRecommendations(analysisData, recommendationsMetric));
      setError(null);
    } catch (e) {
      setError('Erro ao processar dados para análise.');
    }
  }, [analysisData]);

  const handleAnalyzeData = async () => {
    if (!analysisData) {
      setError('Sem dados reais carregados.');
      return;
    }
    setLoading(true);
    try {
      setAiAnalysis(deriveAnalysisText(analysisData, question));
      setActiveSection('analysis');
    } catch (e) {
      setError('Erro ao gerar análise.');
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateInsights = async () => {
    if (!analysisData) {
      setError('Sem dados reais carregados.');
      return;
    }
    setLoading(true);
    try {
      setInsights(deriveInsights(analysisData));
      setActiveSection('insights');
    } catch (e) {
      setError('Erro ao gerar insights.');
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateRecommendations = async () => {
    if (!analysisData) {
      setError('Sem dados reais carregados.');
      return;
    }
    setLoading(true);
    try {
      setRecommendations(deriveRecommendations(analysisData, recommendationsMetric));
      setActiveSection('recommendations');
    } catch (e) {
      setError('Erro ao gerar recomendações.');
    } finally {
      setLoading(false);
    }
  };

  // Componentes de visualização (sem alterações de layout)
  const InsightsView = () => (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">
          <LightbulbIcon sx={{ mr: 1, verticalAlign: 'middle', color: 'primary.main' }} />
          Insights Automáticos
        </Typography>
        <Button
          variant="outlined"
          size="small"
          onClick={handleGenerateInsights}
          startIcon={<RefreshIcon />}
          disabled={loading}
        >
          Gerar Insights
        </Button>
      </Box>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      ) : insights.length > 0 ? (
        <List>
          {insights.map((insight, index) => (
            <ListItem key={index} alignItems="flex-start" sx={{ mb: 1, p: 2, borderRadius: 1, border: '1px solid', borderColor: 'divider' }}>
              <ListItemIcon sx={{ mt: 0.5 }}>
                <LightbulbIcon color={insight.importance > 0.85 ? 'warning' : 'info'} />
              </ListItemIcon>
              <ListItemText
                primary={<Typography variant="subtitle1" fontWeight="medium">{insight.title}</Typography>}
                secondary={<Typography variant="body2" sx={{ mt: 0.5 }}>{insight.description}</Typography>}
              />
            </ListItem>
          ))}
        </List>
      ) : (
        <Box sx={{ py: 3, textAlign: 'center' }}>
          <Typography color="text.secondary">Nenhum insight disponível</Typography>
        </Box>
      )}
    </Box>
  );

  const AIAnalysisView = () => (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h6" sx={{ mb: 2 }}>
          <PsychologyIcon sx={{ mr: 1, verticalAlign: 'middle', color: 'primary.main' }} />
          Análise Inteligente de Dados
        </Typography>

        <Box sx={{ display: 'flex', gap: 1, mb: 3 }}>
          <TextField
            fullWidth
            variant="outlined"
            size="small"
            placeholder="Faça uma pergunta sobre os dados (ex: Quais são os melhores produtos?)"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
          />
          <Button
            variant="contained"
            onClick={handleAnalyzeData}
            disabled={loading}
            startIcon={loading ? <CircularProgress size={20} /> : <SendIcon />}
          >
            Analisar
          </Button>
        </Box>

        {aiAnalysis ? (
          <Paper variant="outlined" sx={{ p: 3, borderRadius: 2 }}>
            <Typography variant="body2" color="text.secondary">{aiAnalysis}</Typography>
          </Paper>
        ) : (
          <Box sx={{ py: 4, textAlign: 'center' }}>
            <Typography color="text.secondary">Nenhuma análise disponível.</Typography>
          </Box>
        )}
      </Box>
    </Box>
  );

  const RecommendationsView = () => (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">
          <BarChartIcon sx={{ mr: 1, verticalAlign: 'middle', color: 'primary.main' }} />
          Recomendações de Negócios
        </Typography>

        <Box sx={{ display: 'flex', gap: 1 }}>
          <FormControl size="small" sx={{ minWidth: 120 }}>
            <InputLabel>Métrica</InputLabel>
            <Select value={recommendationsMetric} onChange={(e) => setRecommendationsMetric(e.target.value)} label="Métrica" size="small">
              <MenuItem value="sales">Vendas</MenuItem>
              <MenuItem value="price">Preço</MenuItem>
              <MenuItem value="reputation">Reputação</MenuItem>
            </Select>
          </FormControl>

          <Button variant="outlined" size="small" onClick={handleGenerateRecommendations} startIcon={<RefreshIcon />} disabled={loading}>
            Gerar Recomendações
          </Button>
        </Box>
      </Box>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      ) : recommendations.length > 0 ? (
        <Grid container spacing={2}>
          {recommendations.map((rec, index) => (
            <Grid item xs={12} key={index}>
              <Card variant="outlined">
                <CardContent>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <Typography variant="h6" gutterBottom>{rec.title}</Typography>
                    <Chip label={`Impacto: ${Math.round((rec.impact||0) * 100)}%`} color={(rec.impact||0) > 0.85 ? 'success' : 'primary'} size="small" />
                  </Box>
                  <Typography variant="body1">{rec.description}</Typography>
                  <Box sx={{ display: 'flex', mt: 2, gap: 1 }}>
                    <Chip label={`Esforço: ${Math.round((rec.effort||0) * 100)}%`} color={(rec.effort||0) < 0.5 ? 'success' : (rec.effort||0) < 0.7 ? 'info' : 'warning'} size="small" variant="outlined" />
                    <Chip label={rec.category} size="small" variant="outlined" />
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      ) : (
        <Box sx={{ py: 3, textAlign: 'center' }}>
          <Typography color="text.secondary">Nenhuma recomendação disponível</Typography>
        </Box>
      )}
    </Box>
  );

  return (
    <Box sx={{ mb: 4 }}>
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Paper elevation={0} sx={{ p: 0, mb: 3, borderRadius: 2 }}>
        <Tabs value={activeSection} onChange={(e, newValue) => setActiveSection(newValue)} sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tab value="insights" label="Insights Automáticos" />
          <Tab value="analysis" label="Análise Inteligente" />
          <Tab value="recommendations" label="Recomendações" />
        </Tabs>

        <Box sx={{ p: 3 }}>
          {activeSection === 'insights' && <InsightsView />}
          {activeSection === 'analysis' && <AIAnalysisView />}
          {activeSection === 'recommendations' && <RecommendationsView />}
        </Box>
      </Paper>
    </Box>
  );
};

export default DataAnalysisAI;
