import { get, post, put, del } from './api';

// Add missing 'del' method to api.js if it doesn't exist
// This method should be added to api.js in a real implementation

// Get all products
export const getAllProducts = async () => {
  return await get('/api/products/');
};

// Get a single product by ID
export const getProductById = async (productId) => {
  return await get(`/api/products/${productId}`);
};

// Create a new product
export const createProduct = async (productData) => {
  return await post('/api/products/', productData);
};

// Update an existing product
export const updateProduct = async (productId, productData) => {
  return await put(`/api/products/${productId}`, productData);
};

// Delete a product
export const deleteProduct = async (productId) => {
  return await del(`/api/products/${productId}`);
};

// Create multiple products in bulk
export const createBulkProducts = async (productsData) => {
  return await post('/api/products/bulk-import', productsData);
};

// Função removida: uploadProductsExcel não era usada e a rota não existia

// Map frontend product model to backend API model
export const mapToApiModel = (product) => {
  return {
    name: product.name,
    pn: product.code,
    search_terms: product.name, // Using name as search terms for now
    family: product.category,
    reference_price: parseFloat(product.referencePrice) || parseFloat(product.currentPrice) || 0,
    is_active: product.status === 'active'
  };
};

// Map backend API model to frontend product model
export const mapFromApiModel = (apiProduct) => {
  return {
    id: apiProduct.product_id || apiProduct.id || Math.random().toString(36).substr(2, 9),
    name: apiProduct.title || apiProduct.name || 'Produto sem nome',
    code: apiProduct.product_id || apiProduct.pn || apiProduct.code || 'N/A',
    category: apiProduct.cartridge_model || apiProduct.family || 'outros',
    currentPrice: parseFloat(apiProduct.price || apiProduct.current_price || apiProduct.reference_price || 0),
    referencePrice: parseFloat(apiProduct.reference_price || apiProduct.price || 0),
    seller: apiProduct.seller_name || apiProduct.seller || 'Não especificado',
    authorized: apiProduct.is_original || apiProduct.is_authorized || false,
    lastUpdate: apiProduct.timestamp || apiProduct.last_update || new Date().toISOString(),
    priceVariation: parseFloat(apiProduct.price_variation || 0),
    hasAlert: apiProduct.has_alert || false,
    status: (apiProduct.is_active !== false && apiProduct.status !== 'inactive') ? 'active' : 'inactive',
    createdAt: apiProduct.created_at || apiProduct.timestamp || new Date().toISOString(),
    imageUrl: apiProduct.image_url || '',
    rating: parseFloat(apiProduct.rating || 0),
    reviewCount: parseInt(apiProduct.review_count || 0),
    stock: parseInt(apiProduct.stock || 0),
    freeShipping: apiProduct.free_shipping || false,
    url: apiProduct.url || '#'
  };
};
