import { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  CircularProgress,
  Alert,
  Chip,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Badge,
  LinearProgress,
  Tooltip,
  IconButton
} from '@mui/material';
import {
  ExpandMore as ExpandMoreIcon,
  Warning as WarningIcon,
  Security as SecurityIcon,
  Report as ReportIcon,
  OpenInNew as OpenInNewIcon,
  Refresh as RefreshIcon
} from '@mui/icons-material';
import dashboardService from '../../services/dashboardService';

// Cores para diferentes níveis de suspeita
const SUSPICION_COLORS = {
  'MUITO_ALTO': '#d32f2f',
  'ALTO': '#f57c00',
  'MEDIO': '#fbc02d',
  'BAIXO': '#388e3c'
};

const FraudDetectionDashboard = () => {
  // Estados para dados
  const [suspiciousSellers, setSuspiciousSellers] = useState([]);
  const [fraudSummary, setFraudSummary] = useState(null);
  const [loading, setLoading] = useState({
    sellers: true,
    summary: true
  });
  const [error, setError] = useState(null);

  // Estados para filtros
  const [periodDays, setPeriodDays] = useState(30);
  const [priceThreshold, setPriceThreshold] = useState(0.6);
  const [limit, setLimit] = useState(20);

  // Carregar dados de detecção de fraudes
  const loadFraudData = useCallback(async () => {
    setLoading({ sellers: true, summary: true });
    setError(null);

    try {
      const [sellersResponse, summaryResponse] = await Promise.all([
        dashboardService.getSuspiciousSellersRanking(limit, periodDays, priceThreshold),
        dashboardService.getFraudDetectionSummary(periodDays)
      ]);

      if (sellersResponse?.success) {
        setSuspiciousSellers(sellersResponse.data || []);
      } else {
        setSuspiciousSellers([]);
      }

      if (summaryResponse?.success) {
        setFraudSummary(summaryResponse.data || {});
      } else {
        setFraudSummary({});
      }

    } catch (err) {
      console.error('Erro ao carregar dados de fraude:', err);
      setError('Falha ao carregar dados de detecção de fraudes. Tente novamente.');
      setSuspiciousSellers([]);
      setFraudSummary({});
    } finally {
      setLoading({ sellers: false, summary: false });
    }
  }, [limit, periodDays, priceThreshold]);

  // Carregar dados ao montar o componente
  useEffect(() => {
    loadFraudData();
  }, [loadFraudData]);

  // Formatador de preço
  const formatPrice = (value) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  // Componente de badge para nível de suspeita
  const SuspicionBadge = ({ level, score }) => {
    const color = SUSPICION_COLORS[level] || '#666';
    const labels = {
      'MUITO_ALTO': 'Muito Alto',
      'ALTO': 'Alto',
      'MEDIO': 'Médio',
      'BAIXO': 'Baixo'
    };

    return (
      <Tooltip title={`Score: ${score}`}>
        <Chip
          label={labels[level]}
          size="small"
          sx={{
            backgroundColor: color,
            color: 'white',
            fontWeight: 'bold'
          }}
        />
      </Tooltip>
    );
  };

  // Componente de card de vendedor suspeito
  const SuspiciousSellerCard = ({ seller, index }) => (
    <Accordion key={index}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
        <Grid container alignItems="center" spacing={2}>
          <Grid item xs={1}>
            <Badge badgeContent={index + 1} color="primary">
              <SecurityIcon color="error" />
            </Badge>
          </Grid>
          <Grid item xs={3}>
            <Typography variant="subtitle1" fontWeight="bold">
              {seller.vendedor}
            </Typography>
            <Typography variant="body2" color="textSecondary">
              {seller.categoria} - {seller.marca}
            </Typography>
          </Grid>
          <Grid item xs={2}>
            <SuspicionBadge level={seller.nivel_suspeita} score={seller.score_suspeita} />
          </Grid>
          <Grid item xs={2}>
            <Typography variant="body2">
              <strong>{seller.diferenca_percentual}%</strong> abaixo da média
            </Typography>
          </Grid>
          <Grid item xs={2}>
            <Typography variant="body2">
              {seller.total_produtos} produtos
            </Typography>
          </Grid>
          <Grid item xs={2}>
            <Typography variant="body2" color="primary">
              {formatPrice(seller.preco_medio_vendedor)}
            </Typography>
          </Grid>
        </Grid>
      </AccordionSummary>

      <AccordionDetails>
        <Grid container spacing={3}>
          {/* Estatísticas do vendedor */}
          <Grid item xs={12} md={6}>
            <Typography variant="h6" gutterBottom>
              Estatísticas do Vendedor
            </Typography>
            <Table size="small">
              <TableBody>
                <TableRow>
                  <TableCell>Preço Médio</TableCell>
                  <TableCell>{formatPrice(seller.preco_medio_vendedor)}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Preço da Categoria</TableCell>
                  <TableCell>{formatPrice(seller.preco_medio_categoria)}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Faixa de Preços</TableCell>
                  <TableCell>
                    {formatPrice(seller.preco_minimo)} - {formatPrice(seller.preco_maximo)}
                  </TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Avaliação Média</TableCell>
                  <TableCell>
                    {seller.rating_medio ? `${seller.rating_medio}/5` : 'N/A'}
                  </TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>Produtos Únicos</TableCell>
                  <TableCell>
                    {seller.produtos_unicos} de {seller.total_produtos}
                  </TableCell>
                </TableRow>
              </TableBody>
            </Table>
          </Grid>

          {/* Indicadores de fraude */}
          <Grid item xs={12} md={6}>
            <Typography variant="h6" gutterBottom>
              Indicadores de Fraude
            </Typography>
            <Box>
              {seller.indicadores_fraude?.map((indicator, idx) => (
                <Chip
                  key={idx}
                  label={indicator}
                  color="warning"
                  size="small"
                  sx={{ m: 0.5 }}
                  icon={<WarningIcon />}
                />
              ))}
            </Box>

            {/* Progress bar do score de suspeita */}
            <Box mt={2}>
              <Typography variant="body2" gutterBottom>
                Score de Suspeita: {seller.score_suspeita}/100
              </Typography>
              <LinearProgress
                variant="determinate"
                value={Math.min(seller.score_suspeita, 100)}
                color={seller.score_suspeita > 70 ? 'error' : seller.score_suspeita > 50 ? 'warning' : 'success'}
                sx={{ height: 8, borderRadius: 4 }}
              />
            </Box>
          </Grid>

          {/* Produtos suspeitos */}
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom>
              Produtos Mais Suspeitos
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Produto</TableCell>
                    <TableCell>Preço</TableCell>
                    <TableCell>Avaliação</TableCell>
                    <TableCell>Data</TableCell>
                    <TableCell>Ações</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {seller.produtos_suspeitos?.slice(0, 3).map((product, idx) => (
                    <TableRow key={idx}>
                      <TableCell>
                        <Typography variant="body2" noWrap>
                          {product.titulo?.substring(0, 50)}...
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="error" fontWeight="bold">
                          {formatPrice(product.preco)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        {product.rating ? `${product.rating}/5` : 'N/A'}
                      </TableCell>
                      <TableCell>
                        {new Date(product.data_coleta).toLocaleDateString('pt-BR')}
                      </TableCell>
                      <TableCell>
                        <IconButton
                          size="small"
                          onClick={() => window.open(product.url, '_blank')}
                          disabled={!product.url}
                        >
                          <OpenInNewIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Grid>
        </Grid>
      </AccordionDetails>
    </Accordion>
  );

  return (
    <Box>
      <Typography variant="h4" component="h1" gutterBottom align="center">
        Dashboard de Detecção de Fraudes
      </Typography>
      <Typography variant="subtitle1" align="center" color="textSecondary" gutterBottom>
        Identificação de vendedores suspeitos de produtos não originais
      </Typography>

      {/* Filtros */}
      <Paper sx={{ p: 2, mb: 4 }}>
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} sm={3}>
            <FormControl fullWidth>
              <InputLabel>Período de Análise</InputLabel>
              <Select
                variant="outlined"
                value={periodDays}
                onChange={(e) => setPeriodDays(e.target.value)}
                label="Período de Análise"
              >
                <MenuItem value={7}>Últimos 7 dias</MenuItem>
                <MenuItem value={15}>Últimos 15 dias</MenuItem>
                <MenuItem value={30}>Últimos 30 dias</MenuItem>
                <MenuItem value={60}>Últimos 60 dias</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} sm={3}>
            <FormControl fullWidth>
              <InputLabel>Threshold de Preço</InputLabel>
              <Select
                variant="outlined"
                value={priceThreshold}
                onChange={(e) => setPriceThreshold(e.target.value)}
                label="Threshold de Preço"
              >
                <MenuItem value={0.4}>60% abaixo da média</MenuItem>
                <MenuItem value={0.6}>40% abaixo da média</MenuItem>
                <MenuItem value={0.7}>30% abaixo da média</MenuItem>
                <MenuItem value={0.8}>20% abaixo da média</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} sm={3}>
            <FormControl fullWidth>
              <InputLabel>Número de Vendedores</InputLabel>
              <Select
                variant="outlined"
                value={limit}
                onChange={(e) => setLimit(e.target.value)}
                label="Número de Vendedores"
              >
                <MenuItem value={10}>Top 10</MenuItem>
                <MenuItem value={20}>Top 20</MenuItem>
                <MenuItem value={50}>Top 50</MenuItem>
                <MenuItem value={100}>Top 100</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} sm={3}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              onClick={loadFraudData}
              startIcon={<RefreshIcon />}
            >
              Atualizar Análise
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {/* Mensagem de erro */}
      {error && (
        <Alert severity="error" sx={{ mb: 4 }}>
          {error}
        </Alert>
      )}

      {/* Resumo executivo */}
      {!loading.summary && fraudSummary && (
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  Total de Vendedores
                </Typography>
                <Typography variant="h4">
                  {fraudSummary.total_vendedores || 0}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  Vendedores Suspeitos
                </Typography>
                <Typography variant="h4" color="error">
                  {fraudSummary.vendedores_suspeitos || 0}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  Taxa de Suspeição
                </Typography>
                <Typography variant="h4" color="warning.main">
                  {fraudSummary.taxa_vendedores_suspeitos || 0}%
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Typography color="textSecondary" gutterBottom>
                  Produtos Analisados
                </Typography>
                <Typography variant="h4">
                  {fraudSummary.total_produtos_analisados || 0}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Ranking de vendedores suspeitos */}
      <Paper sx={{ p: 2 }}>
        <Typography variant="h5" gutterBottom>
          <SecurityIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
          Ranking de Vendedores Suspeitos
        </Typography>

        {loading.sellers ? (
          <Box display="flex" justifyContent="center" alignItems="center" height="200px">
            <CircularProgress />
          </Box>
        ) : suspiciousSellers.length > 0 ? (
          <Box>
            <Typography variant="body2" color="textSecondary" gutterBottom>
              Exibindo {suspiciousSellers.length} vendedores suspeitos detectados
            </Typography>
            {suspiciousSellers.map((seller, index) => (
              <SuspiciousSellerCard key={index} seller={seller} index={index} />
            ))}
          </Box>
        ) : (
          <Alert severity="info">
            Nenhum vendedor suspeito detectado com os critérios atuais.
            Tente ajustar os filtros para uma análise mais ampla.
          </Alert>
        )}
      </Paper>

      {/* Alertas do sistema */}
      {fraudSummary?.alertas && fraudSummary.alertas.length > 0 && (
        <Paper sx={{ p: 2, mt: 4 }}>
          <Typography variant="h6" gutterBottom>
            <ReportIcon sx={{ mr: 1, verticalAlign: 'middle' }} />
            Alertas do Sistema
          </Typography>
          {fraudSummary.alertas.map((alert, index) => (
            <Alert key={index} severity="warning" sx={{ mb: 1 }}>
              {alert}
            </Alert>
          ))}
        </Paper>
      )}
    </Box>
  );
};

export default FraudDetectionDashboard;
