import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Button,
  CircularProgress,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
  Chip,
  Divider,
  Alert,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Tooltip,
  Tabs,
  Tab,
  Switch,
  FormControlLabel,
  TablePagination,
  InputAdornment
} from '@mui/material';
import {
  Check,
  Close,
  HourglassEmpty,
  AdminPanelSettings,
  PersonAdd,
  Edit,
  Delete,
  Search,
  Visibility,
  VisibilityOff
} from '@mui/icons-material';
import axios from 'axios';
import { useAuth } from '../../../hooks/useAuth';

// Função para obter o token
const getTokenFromStorage = (authToken) => {
  if (authToken) {
    return authToken;
  }
  return localStorage.getItem('token');
};

const UserManagement = () => {
  const { token: authToken, user } = useAuth();
  const [activeTab, setActiveTab] = useState(0);
  
  // Estados para usuários cadastrados
  const [users, setUsers] = useState([]);
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRole, setFilterRole] = useState('all');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  
  // Estados para usuários pendentes
  const [pendingUsers, setPendingUsers] = useState([]);
  
  // Estados gerais
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [permissionError, setPermissionError] = useState(false);

  // Estados para diálogos
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [approveDialogOpen, setApproveDialogOpen] = useState(false);
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
  
  // Estados para usuário selecionado
  const [selectedUser, setSelectedUser] = useState(null);
  const [selectedRole, setSelectedRole] = useState('visitor');
  const [rejectionReason, setRejectionReason] = useState('');
  
  // Estados para formulário de novo usuário
  const [newUserForm, setNewUserForm] = useState({
    email: '',
    full_name: '',
    password: '',
    role: 'visitor',
    requires_2fa: false,
    is_active: true
  });
  const [showPassword, setShowPassword] = useState(false);

  // Buscar todos os usuários
  const fetchUsers = useCallback(async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) {
        setError('Sessão expirada. Por favor, faça login novamente.');
        return;
      }

      const response = await axios.get('/api/users/', {
        headers: { Authorization: `Bearer ${token}` }
      });

      setUsers(response.data || []);
      setPermissionError(false);
    } catch (err) {
      console.error('Erro ao buscar usuários:', err);
      if (err.response?.status === 403) {
        setPermissionError(true);
        setError('Permissão insuficiente. Apenas administradores podem gerenciar usuários.');
      } else {
        setError(`Erro ao carregar usuários: ${err.response?.data?.detail || err.message}`);
      }
    }
  }, [authToken]);

  // Buscar usuários pendentes
  const fetchPendingUsers = useCallback(async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) return;

      const response = await axios.get('/api/users/pending-approval', {
        headers: { Authorization: `Bearer ${token}` }
      });

      setPendingUsers(response.data || []);
    } catch (err) {
      console.error('Erro ao buscar usuários pendentes:', err);
      // Para usuários pendentes, não mostramos erro se não houver permissão
      if (err.response?.status !== 403) {
        console.warn('Não foi possível carregar usuários pendentes');
      }
    }
  }, [authToken]);

  // Carregar dados iniciais
  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      await Promise.all([fetchUsers(), fetchPendingUsers()]);
      setLoading(false);
    };
    loadData();
  }, [fetchUsers, fetchPendingUsers]);

  // Filtrar usuários
  useEffect(() => {
    let filtered = users;

    if (searchTerm) {
      filtered = filtered.filter(user =>
        user.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        user.email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (filterRole !== 'all') {
      filtered = filtered.filter(user => user.role === filterRole);
    }

    setFilteredUsers(filtered);
    setPage(0);
  }, [users, searchTerm, filterRole]);

  // Criar usuário
  const handleCreateUser = async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) {
        setError('Sessão expirada. Por favor, faça login novamente.');
        return;
      }

      await axios.post('/api/users/', newUserForm, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setCreateDialogOpen(false);
      setNewUserForm({
        email: '',
        full_name: '',
        password: '',
        role: 'visitor',
        requires_2fa: false,
        is_active: true
      });
      
      await fetchUsers();
      setError({ severity: 'success', message: 'Usuário criado com sucesso!' });
    } catch (err) {
      console.error('Erro ao criar usuário:', err);
      setError({ severity: 'error', message: `Erro ao criar usuário: ${err.response?.data?.detail || err.message}` });
    }
  };

  // Editar usuário
  const handleEditUser = async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) return;

      const updateData = {
        full_name: selectedUser.full_name,
        role: selectedUser.role,
        is_active: selectedUser.is_active,
        requires_2fa: selectedUser.requires_2fa
      };

      await axios.put(`/api/users/${selectedUser.id}`, updateData, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setEditDialogOpen(false);
      await fetchUsers();
      setError({ severity: 'success', message: 'Usuário atualizado com sucesso!' });
    } catch (err) {
      console.error('Erro ao editar usuário:', err);
      setError({ severity: 'error', message: `Erro ao editar usuário: ${err.response?.data?.detail || err.message}` });
    }
  };

  // Deletar usuário
  const handleDeleteUser = async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) return;

      await axios.delete(`/api/users/${selectedUser.id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setDeleteDialogOpen(false);
      await fetchUsers();
      setError({ severity: 'success', message: 'Usuário removido com sucesso!' });
    } catch (err) {
      console.error('Erro ao deletar usuário:', err);
      setError({ severity: 'error', message: `Erro ao deletar usuário: ${err.response?.data?.detail || err.message}` });
    }
  };

  // Aprovar usuário
  const handleApproveUser = async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) return;

      await axios.post(`/api/users/${selectedUser.id}/approve`, { role: selectedRole }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setApproveDialogOpen(false);
      await Promise.all([fetchUsers(), fetchPendingUsers()]);
      setError({ severity: 'success', message: `Usuário ${selectedUser.full_name} aprovado com sucesso!` });
    } catch (err) {
      console.error('Erro ao aprovar usuário:', err);
      setError({ severity: 'error', message: 'Erro ao aprovar usuário. Por favor, tente novamente.' });
    }
  };

  // Rejeitar usuário
  const handleRejectUser = async () => {
    try {
      const token = getTokenFromStorage(authToken);
      if (!token) return;

      await axios.post(`/api/users/${selectedUser.id}/reject`, { reason: rejectionReason }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setRejectDialogOpen(false);
      await fetchPendingUsers();
      setError({ severity: 'success', message: `Cadastro de ${selectedUser.full_name} rejeitado.` });
    } catch (err) {
      console.error('Erro ao rejeitar usuário:', err);
      setError({ severity: 'error', message: 'Erro ao rejeitar usuário. Por favor, tente novamente.' });
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleString('pt-BR');
  };

  const getRoleLabel = (role) => {
    const roles = {
      visitor: 'Visitante',
      user: 'Usuário',
      analyst: 'Analista',
      editor: 'Editor',
      admin: 'Administrador'
    };
    return roles[role] || role;
  };

  const getRoleColor = (role) => {
    const colors = {
      visitor: 'default',
      user: 'primary',
      analyst: 'secondary',
      editor: 'warning',
      admin: 'error'
    };
    return colors[role] || 'default';
  };

  // Renderizar lista de usuários cadastrados
  const renderUsersTable = () => {
    const paginatedUsers = filteredUsers.slice(
      page * rowsPerPage,
      page * rowsPerPage + rowsPerPage
    );

    return (
      <Box>
        {/* Cabeçalho e filtros */}
        <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2 }}>
          <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
            <TextField
              label="Buscar usuários"
              variant="outlined"
              size="small"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                )
              }}
              sx={{ minWidth: 250 }}
            />
            <FormControl size="small" sx={{ minWidth: 150 }}>
              <InputLabel>Filtrar por cargo</InputLabel>
              <Select
                value={filterRole}
                label="Filtrar por cargo"
                onChange={(e) => setFilterRole(e.target.value)}
              >
                <MenuItem value="all">Todos</MenuItem>
                <MenuItem value="visitor">Visitante</MenuItem>
                <MenuItem value="user">Usuário</MenuItem>
                <MenuItem value="analyst">Analista</MenuItem>
                <MenuItem value="editor">Editor</MenuItem>
                <MenuItem value="admin">Administrador</MenuItem>
              </Select>
            </FormControl>
          </Box>
          <Button
            variant="contained"
            startIcon={<PersonAdd />}
            onClick={() => setCreateDialogOpen(true)}
          >
            Novo Usuário
          </Button>
        </Box>

        {/* Tabela */}
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Nome</TableCell>
                <TableCell>Email</TableCell>
                <TableCell>Cargo</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>2FA</TableCell>
                <TableCell>Criado em</TableCell>
                <TableCell align="center">Ações</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedUsers.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>{user.full_name}</TableCell>
                  <TableCell>{user.email}</TableCell>
                  <TableCell>
                    <Chip
                      label={getRoleLabel(user.role)}
                      color={getRoleColor(user.role)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={user.is_active ? 'Ativo' : 'Inativo'}
                      color={user.is_active ? 'success' : 'default'}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={user.requires_2fa ? 'Ativo' : 'Inativo'}
                      color={user.requires_2fa ? 'success' : 'default'}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>{formatDate(user.created_at)}</TableCell>
                  <TableCell align="center">
                    <Tooltip title="Editar">
                      <IconButton
                        size="small"
                        onClick={() => {
                          setSelectedUser(user);
                          setEditDialogOpen(true);
                        }}
                      >
                        <Edit />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Excluir">
                      <IconButton
                        size="small"
                        color="error"
                        onClick={() => {
                          setSelectedUser(user);
                          setDeleteDialogOpen(true);
                        }}
                        disabled={user.id === user?.id} // Não pode excluir a si mesmo
                      >
                        <Delete />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Paginação */}
        <TablePagination
          component="div"
          count={filteredUsers.length}
          page={page}
          onPageChange={(e, newPage) => setPage(newPage)}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={(e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          }}
          labelRowsPerPage="Linhas por página:"
          labelDisplayedRows={({ from, to, count }) => `${from}-${to} de ${count}`}
        />
      </Box>
    );
  };

  // Renderizar lista de usuários pendentes
  const renderPendingUsers = () => {
    if (pendingUsers.length === 0) {
      return (
        <Alert severity="info">
          Não há usuários pendentes de aprovação no momento.
        </Alert>
      );
    }

    return (
      <Grid container spacing={3}>
        {pendingUsers.map((user) => (
          <Grid item xs={12} md={6} key={user.id}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                  <Typography variant="h6">{user.full_name}</Typography>
                  <Chip
                    icon={<HourglassEmpty />}
                    label="Pendente"
                    color="warning"
                    size="small"
                  />
                </Box>

                <Typography variant="body1" color="text.secondary">
                  Email: {user.email}
                </Typography>

                <Typography variant="body2" color="text.secondary">
                  Data de cadastro: {formatDate(user.created_at)}
                </Typography>

                <Divider sx={{ my: 2 }} />

                <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                  <Button
                    variant="outlined"
                    color="error"
                    startIcon={<Close />}
                    onClick={() => {
                      setSelectedUser(user);
                      setRejectDialogOpen(true);
                    }}
                  >
                    Rejeitar
                  </Button>
                  <Button
                    variant="contained"
                    color="success"
                    startIcon={<Check />}
                    onClick={() => {
                      setSelectedUser(user);
                      setSelectedRole('visitor');
                      setApproveDialogOpen(true);
                    }}
                  >
                    Aprovar
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    );
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Gerenciamento de Usuários
      </Typography>

      {/* Banner informativo */}
      <Paper
        elevation={3}
        sx={{
          p: 3,
          mb: 4,
          bgcolor: 'primary.light',
          color: 'primary.contrastText',
          borderLeft: '6px solid',
          borderColor: 'primary.main'
        }}
      >
        <Typography variant="h5" fontWeight="bold" gutterBottom>
          Painel de Controle de Usuários
        </Typography>
        <Typography variant="body1">
          Gerencie todos os usuários do sistema: visualize usuários cadastrados, crie novos usuários,
          edite permissões e aprove solicitações de cadastro pendentes.
        </Typography>
        <Typography variant="body2" sx={{ mt: 1, opacity: 0.8 }}>
          Status do usuário: <strong>{getRoleLabel(user?.role)}</strong> (email: {user?.email}, role: {user?.role}, is_superuser: {user?.is_superuser ? 'true' : 'false'})
        </Typography>
      </Paper>

      {/* Tratamento de erro de permissão */}
      {permissionError && (
        <Paper
          elevation={3}
          sx={{
            p: 3,
            mb: 4,
            bgcolor: 'warning.light',
            borderLeft: '6px solid',
            borderColor: 'warning.main',
          }}
        >
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <AdminPanelSettings sx={{ fontSize: 40, mr: 2, color: 'warning.dark' }} />
            <Typography variant="h6" fontWeight="bold">
              Acesso Restrito - Permissão de Administrador Necessária
            </Typography>
          </Box>
          <Typography paragraph>
            Esta funcionalidade está disponível apenas para usuários com nível de acesso Administrador.
            Se você precisa gerenciar usuários, entre em contato com o administrador do sistema.
          </Typography>
          <Button
            variant="contained"
            color="primary"
            sx={{ mt: 2 }}
            onClick={() => window.location.href = '/settings'}
          >
            Voltar para Configurações
          </Button>
        </Paper>
      )}

      {/* Alertas de feedback */}
      {error && typeof error === 'object' && !permissionError && (
        <Alert
          severity={error.severity}
          sx={{ mb: 2 }}
          onClose={() => setError(null)}
        >
          {error.message}
        </Alert>
      )}

      {error && typeof error === 'string' && !permissionError && (
        <Alert
          severity="error"
          sx={{ mb: 2 }}
          onClose={() => setError(null)}
        >
          {error}
        </Alert>
      )}

      {/* Conteúdo principal */}
      {!permissionError && (
        <>
          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
            <>
              {/* Abas */}
              <Paper sx={{ mb: 3 }}>
                <Tabs
                  value={activeTab}
                  onChange={(e, newValue) => setActiveTab(newValue)}
                  variant="fullWidth"
                >
                  <Tab label={`Usuários Cadastrados (${users.length})`} />
                  <Tab label={`Pendentes de Aprovação (${pendingUsers.length})`} />
                </Tabs>
              </Paper>

              {/* Conteúdo das abas */}
              <Box sx={{ mt: 3 }}>
                {activeTab === 0 && renderUsersTable()}
                {activeTab === 1 && renderPendingUsers()}
              </Box>
            </>
          )}
        </>
      )}

      {/* Diálogo de Criação de Usuário */}
      <Dialog open={createDialogOpen} onClose={() => setCreateDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Criar Novo Usuário</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="Nome Completo"
              fullWidth
              value={newUserForm.full_name}
              onChange={(e) => setNewUserForm({ ...newUserForm, full_name: e.target.value })}
            />
            <TextField
              label="Email"
              type="email"
              fullWidth
              value={newUserForm.email}
              onChange={(e) => setNewUserForm({ ...newUserForm, email: e.target.value })}
            />
            <TextField
              label="Senha"
              type={showPassword ? 'text' : 'password'}
              fullWidth
              value={newUserForm.password}
              onChange={(e) => setNewUserForm({ ...newUserForm, password: e.target.value })}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={() => setShowPassword(!showPassword)}
                      edge="end"
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                )
              }}
            />
            <FormControl fullWidth>
              <InputLabel>Cargo</InputLabel>
              <Select
                value={newUserForm.role}
                label="Cargo"
                onChange={(e) => setNewUserForm({ ...newUserForm, role: e.target.value })}
              >
                <MenuItem value="visitor">Visitante</MenuItem>
                <MenuItem value="user">Usuário</MenuItem>
                <MenuItem value="analyst">Analista</MenuItem>
                <MenuItem value="editor">Editor</MenuItem>
                <MenuItem value="admin">Administrador</MenuItem>
              </Select>
            </FormControl>
            <FormControlLabel
              control={
                <Switch
                  checked={newUserForm.is_active}
                  onChange={(e) => setNewUserForm({ ...newUserForm, is_active: e.target.checked })}
                />
              }
              label="Usuário ativo"
            />
            <FormControlLabel
              control={
                <Switch
                  checked={newUserForm.requires_2fa}
                  onChange={(e) => setNewUserForm({ ...newUserForm, requires_2fa: e.target.checked })}
                />
              }
              label="Requer autenticação 2FA"
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>Cancelar</Button>
          <Button onClick={handleCreateUser} variant="contained" color="primary">
            Criar Usuário
          </Button>
        </DialogActions>
      </Dialog>

      {/* Diálogo de Edição de Usuário */}
      <Dialog open={editDialogOpen} onClose={() => setEditDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Editar Usuário</DialogTitle>
        <DialogContent>
          {selectedUser && (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
              <TextField
                label="Nome Completo"
                fullWidth
                value={selectedUser.full_name || ''}
                onChange={(e) => setSelectedUser({ ...selectedUser, full_name: e.target.value })}
              />
              <TextField
                label="Email"
                fullWidth
                value={selectedUser.email || ''}
                disabled
                helperText="Email não pode ser alterado"
              />
              <FormControl fullWidth>
                <InputLabel>Cargo</InputLabel>
                <Select
                  value={selectedUser.role || 'visitor'}
                  label="Cargo"
                  onChange={(e) => setSelectedUser({ ...selectedUser, role: e.target.value })}
                >
                  <MenuItem value="visitor">Visitante</MenuItem>
                  <MenuItem value="user">Usuário</MenuItem>
                  <MenuItem value="analyst">Analista</MenuItem>
                  <MenuItem value="editor">Editor</MenuItem>
                  <MenuItem value="admin">Administrador</MenuItem>
                </Select>
              </FormControl>
              <FormControlLabel
                control={
                  <Switch
                    checked={selectedUser.is_active || false}
                    onChange={(e) => setSelectedUser({ ...selectedUser, is_active: e.target.checked })}
                  />
                }
                label="Usuário ativo"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={selectedUser.requires_2fa || false}
                    onChange={(e) => setSelectedUser({ ...selectedUser, requires_2fa: e.target.checked })}
                  />
                }
                label="Requer autenticação 2FA"
              />
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)}>Cancelar</Button>
          <Button onClick={handleEditUser} variant="contained" color="primary">
            Salvar Alterações
          </Button>
        </DialogActions>
      </Dialog>

      {/* Diálogo de Exclusão */}
      <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
        <DialogTitle>Confirmar Exclusão</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Tem certeza que deseja excluir o usuário <strong>{selectedUser?.full_name}</strong>?
            Esta ação não pode ser desfeita.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)}>Cancelar</Button>
          <Button onClick={handleDeleteUser} variant="contained" color="error">
            Excluir
          </Button>
        </DialogActions>
      </Dialog>

      {/* Diálogo de Aprovação */}
      <Dialog open={approveDialogOpen} onClose={() => setApproveDialogOpen(false)}>
        <DialogTitle>Aprovar Usuário</DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ mb: 2 }}>
            Você está prestes a aprovar o cadastro de <strong>{selectedUser?.full_name}</strong>.
            Por favor, selecione o nível de acesso que este usuário terá no sistema.
          </DialogContentText>

          <FormControl fullWidth margin="normal">
            <InputLabel id="role-select-label">Nível de Acesso</InputLabel>
            <Select
              labelId="role-select-label"
              value={selectedRole}
              label="Nível de Acesso"
              onChange={(e) => setSelectedRole(e.target.value)}
            >
              <MenuItem value="visitor">Visitante (acesso básico)</MenuItem>
              <MenuItem value="user">Usuário (acesso padrão)</MenuItem>
              <MenuItem value="analyst">Analista (acesso a análises)</MenuItem>
              <MenuItem value="editor">Editor (acesso intermediário)</MenuItem>
              <MenuItem value="admin">Administrador (acesso completo)</MenuItem>
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setApproveDialogOpen(false)} color="inherit">
            Cancelar
          </Button>
          <Button onClick={handleApproveUser} variant="contained" color="success">
            Confirmar Aprovação
          </Button>
        </DialogActions>
      </Dialog>

      {/* Diálogo de Rejeição */}
      <Dialog open={rejectDialogOpen} onClose={() => setRejectDialogOpen(false)}>
        <DialogTitle>Rejeitar Cadastro</DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ mb: 2 }}>
            Você está prestes a rejeitar o cadastro de <strong>{selectedUser?.full_name}</strong>.
            Por favor, forneça um motivo para a rejeição (opcional).
          </DialogContentText>

          <TextField
            autoFocus
            margin="dense"
            id="reason"
            label="Motivo da Rejeição"
            type="text"
            fullWidth
            multiline
            rows={3}
            value={rejectionReason}
            onChange={(e) => setRejectionReason(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setRejectDialogOpen(false)} color="inherit">
            Cancelar
          </Button>
          <Button onClick={handleRejectUser} variant="contained" color="error">
            Confirmar Rejeição
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default UserManagement;
