/**
 * Serviço WebSocket para notificações em tempo real
 */
class WebSocketService {
  constructor() {
    this.socket = null;
    this.isConnected = false;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5;
    this.reconnectDelay = 1000; // ms
    this.messageQueue = [];
    this.subscriptions = new Set();
    
    // Callbacks para eventos
    this.onMessageCallbacks = [];
    this.onConnectCallbacks = [];
    this.onDisconnectCallbacks = [];
    this.onErrorCallbacks = [];
    
    // Bind methods
    this.connect = this.connect.bind(this);
    this.disconnect = this.disconnect.bind(this);
    this.send = this.send.bind(this);
    this.subscribe = this.subscribe.bind(this);
    this.unsubscribe = this.unsubscribe.bind(this);
  }

  /**
   * Determina a URL base para WebSocket
   */
  determineBackendUrl() {
    // 1) Se a variável de ambiente estiver definida, respeite-a
    if (process.env.REACT_APP_API_URL) {
      const url = process.env.REACT_APP_API_URL;
      // Converte http/https para ws/wss
      return url.replace('http:', 'ws:').replace('https:', 'wss:');
    }

    // 2) Se estiver em ambiente local
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
      return `${protocol}//localhost:8000`;
    }

    // 3) Se nenhuma das condições acima for atendida, tente usar o mesmo host
    return `${protocol}//${window.location.hostname}:8000`;
  }

  /**
   * Conecta ao WebSocket
   * @param {string} token - JWT token para autenticação
   * @param {string} clientType - Tipo do cliente
   */
  connect(token, clientType = 'web') {
    if (this.socket && this.socket.readyState === WebSocket.OPEN) {
      console.log('WebSocket já está conectado');
      return;
    }

    try {
      // Configuração simplificada do WebSocket usando caminho relativo
      // Isso permitirá que o proxy configurado no setupProxy.js intercepte e redirecione a conexão
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const host = window.location.host; // Usa sempre o host atual

      const wsUrl = `${protocol}//${host}/ws?token=${encodeURIComponent(token)}&client_type=${clientType}`;

      console.log('Conectando ao WebSocket via caminho relativo:', wsUrl);

      this.socket = new WebSocket(wsUrl);
      
      this.socket.onopen = this.handleOpen.bind(this);
      this.socket.onmessage = this.handleMessage.bind(this);
      this.socket.onclose = this.handleClose.bind(this);
      this.socket.onerror = this.handleError.bind(this);
      
    } catch (error) {
      console.error('Erro ao conectar WebSocket:', error);
      this.handleReconnect();
    }
  }

  /**
   * Desconecta do WebSocket
   */
  disconnect() {
    if (this.socket) {
      this.socket.close(1000, 'Disconnect requested');
      this.socket = null;
    }
    this.isConnected = false;
    this.reconnectAttempts = 0;
  }

  /**
   * Envia mensagem via WebSocket
   * @param {Object} message - Mensagem a ser enviada
   */
  send(message) {
    if (this.socket && this.socket.readyState === WebSocket.OPEN) {
      this.socket.send(JSON.stringify(message));
    } else {
      // Adiciona à fila se não conectado
      this.messageQueue.push(message);
      console.warn('WebSocket não conectado, mensagem adicionada à fila');
    }
  }

  /**
   * Se inscreve em tipos de notificação
   * @param {Array} notificationTypes - Tipos de notificação
   */
  subscribe(notificationTypes) {
    // Adiciona aos subscriptions locais
    notificationTypes.forEach(type => this.subscriptions.add(type));
    
    // Envia comando de subscription
    this.send({
      type: 'subscribe',
      notification_types: notificationTypes
    });
  }

  /**
   * Cancela inscrição em tipos de notificação
   * @param {Array} notificationTypes - Tipos de notificação
   */
  unsubscribe(notificationTypes) {
    // Remove dos subscriptions locais
    notificationTypes.forEach(type => this.subscriptions.delete(type));
    
    // Envia comando de unsubscribe
    this.send({
      type: 'unsubscribe',
      notification_types: notificationTypes
    });
  }

  /**
   * Manipula conexão estabelecida
   */
  handleOpen(event) {
    console.log('WebSocket conectado!', event);
    this.isConnected = true;
    this.reconnectAttempts = 0;
    
    // Processa fila de mensagens
    while (this.messageQueue.length > 0) {
      const message = this.messageQueue.shift();
      this.send(message);
    }
    
    // Reinscreve em notificações
    if (this.subscriptions.size > 0) {
      this.subscribe(Array.from(this.subscriptions));
    }
    
    // Inicia heartbeat
    this.startHeartbeat();
    
    // Chama callbacks de conexão
    this.onConnectCallbacks.forEach(callback => {
      try {
        callback(event);
      } catch (error) {
        console.error('Erro no callback de conexão:', error);
      }
    });
  }

  /**
   * Manipula mensagens recebidas
   */
  handleMessage(event) {
    try {
      const message = JSON.parse(event.data);
      console.log('Mensagem WebSocket recebida:', message);
      
      // Processa mensagens especiais
      if (message.type === 'pong') {
        // Resposta do heartbeat
        return;
      }
      
      if (message.type === 'subscription_confirmed') {
        console.log('Inscrições confirmadas:', message.subscribed_to);
        return;
      }
      
      if (message.type === 'missed_notifications') {
        console.log('Notificações perdidas recebidas:', message.data);
        // Processa notificações perdidas
        message.data.notifications.forEach(notification => {
          this.processNotification(notification);
        });
        return;
      }
      
      // Processa notificação normal
      this.processNotification(message);
      
    } catch (error) {
      console.error('Erro ao processar mensagem WebSocket:', error);
    }
  }

  /**
   * Processa uma notificação
   * @param {Object} notification - Notificação recebida
   */
  processNotification(notification) {
    // Chama callbacks de mensagem
    this.onMessageCallbacks.forEach(callback => {
      try {
        callback(notification);
      } catch (error) {
        console.error('Erro no callback de mensagem:', error);
      }
    });

    // Mostra notificação do browser se permitido
    this.showBrowserNotification(notification);
  }

  /**
   * Mostra notificação nativa do browser
   * @param {Object} notification - Dados da notificação
   */
  showBrowserNotification(notification) {
    if (!('Notification' in window) || Notification.permission !== 'granted') {
      return;
    }

    const title = notification.title || 'Mercado Livre Tracker';
    const options = {
      body: notification.message || '',
      icon: '/favicon-16x16.png',
      badge: '/favicon-16x16.png',
      tag: notification.type || 'general',
      requireInteraction: notification.priority === 'high',
      silent: false
    };

    const browserNotif = new Notification(title, options);
    
    // Auto-close após 5 segundos (exceto alta prioridade)
    if (notification.priority !== 'high') {
      setTimeout(() => browserNotif.close(), 5000);
    }
  }

  /**
   * Manipula fechamento da conexão
   */
  handleClose(event) {
    console.log('WebSocket desconectado:', event);
    this.isConnected = false;
    this.stopHeartbeat();
    
    // Chama callbacks de desconexão
    this.onDisconnectCallbacks.forEach(callback => {
      try {
        callback(event);
      } catch (error) {
        console.error('Erro no callback de desconexão:', error);
      }
    });
    
    // Tenta reconectar se não foi desconexão intencional
    if (event.code !== 1000) {
      this.handleReconnect();
    }
  }

  /**
   * Manipula erros do WebSocket
   */
  handleError(error) {
    console.error('Erro no WebSocket:', error);
    
    // Chama callbacks de erro
    this.onErrorCallbacks.forEach(callback => {
      try {
        callback(error);
      } catch (error) {
        console.error('Erro no callback de erro:', error);
      }
    });
  }

  /**
   * Lida com reconexão automática
   */
  handleReconnect() {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('Máximo de tentativas de reconexão atingido');
      return;
    }

    this.reconnectAttempts++;
    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1); // Backoff exponencial
    
    console.log(`Tentando reconectar em ${delay}ms (tentativa ${this.reconnectAttempts}/${this.maxReconnectAttempts})`);
    
    setTimeout(() => {
      if (!this.isConnected) {
        const token = localStorage.getItem('access_token');
        if (token) {
          this.connect(token);
        }
      }
    }, delay);
  }

  /**
   * Inicia heartbeat para manter conexão viva
   */
  startHeartbeat() {
    this.heartbeatInterval = setInterval(() => {
      if (this.isConnected) {
        this.send({
          type: 'ping',
          timestamp: Date.now()
        });
      }
    }, 30000); // A cada 30 segundos
  }

  /**
   * Para o heartbeat
   */
  stopHeartbeat() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  /**
   * Registra callback para mensagens
   * @param {Function} callback - Função a ser chamada
   */
  onMessage(callback) {
    this.onMessageCallbacks.push(callback);
  }

  /**
   * Registra callback para conexão
   * @param {Function} callback - Função a ser chamada
   */
  onConnect(callback) {
    this.onConnectCallbacks.push(callback);
  }

  /**
   * Registra callback para desconexão
   * @param {Function} callback - Função a ser chamada
   */
  onDisconnect(callback) {
    this.onDisconnectCallbacks.push(callback);
  }

  /**
   * Registra callback para erros
   * @param {Function} callback - Função a ser chamada
   */
  onError(callback) {
    this.onErrorCallbacks.push(callback);
  }

  /**
   * Remove callback
   * @param {Function} callback - Callback a ser removido
   * @param {string} type - Tipo do callback (message, connect, disconnect, error)
   */
  removeCallback(callback, type) {
    const callbacks = {
      message: this.onMessageCallbacks,
      connect: this.onConnectCallbacks,
      disconnect: this.onDisconnectCallbacks,
      error: this.onErrorCallbacks
    };

    const callbackArray = callbacks[type];
    if (callbackArray && Array.isArray(callbackArray)) {
      const index = callbackArray.indexOf(callback);
      if (index !== -1) {
        callbackArray.splice(index, 1);
      }
    }
  }
}

// Singleton do serviço WebSocket
const websocketService = new WebSocketService();

export default websocketService;
