import React, { useState, useEffect, useCallback } from 'react';
import {
  IconButton,
  Badge,
  Popover,
  Paper,
  Typography,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  ListItemSecondaryAction,
  Divider,
  Button,
  Box,
  Chip,
  Avatar
} from '@mui/material';
import {
  Notifications as NotificationsIcon,
  Close as CloseIcon,
  Warning as WarningIcon,
  Info as InfoIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
  Wifi as WifiIcon,
  WifiOff as WifiOffIcon,
  Settings as SettingsIcon
} from '@mui/icons-material';
import { useTheme } from '@mui/material/styles';
import websocketService from '../../services/websocket';

const NotificationCenter = () => {
  const theme = useTheme();
  const [notifications, setNotifications] = useState([]);
  const [anchorEl, setAnchorEl] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [settings, setSettings] = useState({
    priceAlerts: true,
    systemAlerts: true,
    scrapingStatus: true,
    browserNotifications: false
  });

  const isOpen = Boolean(anchorEl);

  // Callback para mensagens WebSocket
  const handleWebSocketMessage = useCallback((message) => {
    const notification = {
      id: Date.now() + Math.random(),
      ...message,
      timestamp: new Date().toISOString(),
      read: false
    };

    setNotifications(prev => [notification, ...prev.slice(0, 49)]); // Mantém apenas 50
    setUnreadCount(prev => prev + 1);

    // Som de notificação
    playNotificationSound(message.priority);
  }, []);

  // Callbacks de conexão
  const handleConnect = useCallback(() => {
    setIsConnected(true);
    console.log('NotificationCenter: WebSocket conectado');
  }, []);

  const handleDisconnect = useCallback(() => {
    setIsConnected(false);
    console.log('NotificationCenter: WebSocket desconectado');
  }, []);

  // Configurar WebSocket
  useEffect(() => {
    const token = localStorage.getItem('access_token');
    if (token) {
      // Registrar callbacks
      websocketService.onMessage(handleWebSocketMessage);
      websocketService.onConnect(handleConnect);
      websocketService.onDisconnect(handleDisconnect);

      // Conectar
      websocketService.connect(token);

      // Solicitar permissão para notificações
      if (settings.browserNotifications) {
        websocketService.constructor.requestNotificationPermission();
      }

      // Inscrever em tipos de notificação baseado nas configurações
      const subscriptions = [];
      if (settings.priceAlerts) subscriptions.push('price_alert');
      if (settings.systemAlerts) subscriptions.push('system_alert');
      if (settings.scrapingStatus) subscriptions.push('scraping_status');
      
      websocketService.subscribe(subscriptions);
    }

    return () => {
      // Limpar callbacks
      websocketService.removeCallback(handleWebSocketMessage, 'message');
      websocketService.removeCallback(handleConnect, 'connect');
      websocketService.removeCallback(handleDisconnect, 'disconnect');
    };
  }, [handleWebSocketMessage, handleConnect, handleDisconnect, settings]);

  const playNotificationSound = (priority) => {
    if ('speechSynthesis' in window && priority === 'high') {
      // Som apenas para prioridade alta
      const audio = new Audio('data:audio/wav;base64,');
      audio.volume = 0.1;
      audio.play().catch(() => {}); // Ignora erros de reprodução
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'price_alert':
        return <WarningIcon color="warning" />;
      case 'system_alert':
        return <ErrorIcon color="error" />;
      case 'scraping_status':
        return <InfoIcon color="info" />;
      default:
        return <CheckCircleIcon color="success" />;
    }
  };

  const getNotificationColor = (type, priority) => {
    if (priority === 'high') return theme.palette.error.light;
    if (priority === 'medium') return theme.palette.warning.light;
    
    switch (type) {
      case 'price_alert':
        return theme.palette.warning.light;
      case 'system_alert':
        return theme.palette.error.light;
      case 'scraping_status':
        return theme.palette.info.light;
      default:
        return theme.palette.success.light;
    }
  };

  const formatTimestamp = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diff = now - date;
    
    if (diff < 60000) return 'Agora mesmo';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m atrás`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h atrás`;
    return date.toLocaleDateString('pt-BR');
  };

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const markAsRead = (id) => {
    setNotifications(prev => 
      prev.map(notif => 
        notif.id === id ? { ...notif, read: true } : notif
      )
    );
    setUnreadCount(prev => Math.max(0, prev - 1));
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(notif => ({ ...notif, read: true })));
    setUnreadCount(0);
  };

  const clearNotification = (id) => {
    setNotifications(prev => prev.filter(notif => notif.id !== id));
    setUnreadCount(prev => {
      const notification = notifications.find(n => n.id === id);
      return notification && !notification.read ? prev - 1 : prev;
    });
  };

  const clearAllNotifications = () => {
    setNotifications([]);
    setUnreadCount(0);
  };

  return (
    <>
      {/* Botão de notificações */}
      <IconButton
        onClick={handleClick}
        color="inherit"
        sx={{ position: 'relative' }}
      >
        <Badge badgeContent={unreadCount} color="error" max={99}>
          <NotificationsIcon />
        </Badge>
        
        {/* Indicador de conexão */}
        <Box sx={{ 
          position: 'absolute', 
          top: 2, 
          left: 2,
          zIndex: 1
        }}>
          {isConnected ? (
            <WifiIcon sx={{ fontSize: 12, color: 'success.main' }} />
          ) : (
            <WifiOffIcon sx={{ fontSize: 12, color: 'error.main' }} />
          )}
        </Box>
      </IconButton>

      {/* Popover de notificações */}
      <Popover
        open={isOpen}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
        PaperProps={{
          sx: { width: 400, maxHeight: 500 }
        }}
      >
        <Paper elevation={3}>
          {/* Header */}
          <Box sx={{ 
            p: 2, 
            borderBottom: 1, 
            borderColor: 'divider',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            backgroundColor: theme.palette.grey[50]
          }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography variant="h6">Notificações</Typography>
              <Chip 
                size="small"
                label={isConnected ? 'Conectado' : 'Desconectado'}
                color={isConnected ? 'success' : 'error'}
                variant="outlined"
              />
            </Box>
            
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              {unreadCount > 0 && (
                <Button
                  size="small"
                  onClick={markAllAsRead}
                  sx={{ textTransform: 'none' }}
                >
                  Marcar todas lidas
                </Button>
              )}
              <IconButton size="small" onClick={handleClose}>
                <CloseIcon fontSize="small" />
              </IconButton>
            </Box>
          </Box>

          {/* Lista de notificações */}
          <Box sx={{ maxHeight: 300, overflow: 'auto' }}>
            {notifications.length === 0 ? (
              <Box sx={{ 
                p: 4, 
                textAlign: 'center',
                color: 'text.secondary'
              }}>
                <NotificationsIcon sx={{ fontSize: 48, mb: 1, opacity: 0.5 }} />
                <Typography>Nenhuma notificação</Typography>
              </Box>
            ) : (
              <List disablePadding>
                {notifications.map((notification, index) => (
                  <React.Fragment key={notification.id}>
                    <ListItem
                      button
                      onClick={() => markAsRead(notification.id)}
                      sx={{
                        backgroundColor: !notification.read 
                          ? `${getNotificationColor(notification.type, notification.priority)}20` 
                          : 'transparent',
                        borderLeft: 4,
                        borderLeftColor: getNotificationColor(notification.type, notification.priority),
                        '&:hover': {
                          backgroundColor: theme.palette.grey[100]
                        }
                      }}
                    >
                      <ListItemIcon>
                        {getNotificationIcon(notification.type)}
                      </ListItemIcon>
                      
                      <ListItemText
                        primary={
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Typography variant="subtitle2" noWrap>
                              {notification.title}
                            </Typography>
                            {!notification.read && (
                              <Box sx={{
                                width: 8,
                                height: 8,
                                borderRadius: '50%',
                                backgroundColor: theme.palette.primary.main
                              }} />
                            )}
                          </Box>
                        }
                        secondary={
                          <Box>
                            <Typography variant="body2" color="text.secondary">
                              {notification.message}
                            </Typography>
                            
                            {/* Dados adicionais */}
                            {notification.data && notification.type === 'price_alert' && notification.data.current_price && (
                              <Box sx={{ mt: 0.5, display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography variant="caption" color="text.secondary">
                                  Preço: R$ {notification.data.current_price.toFixed(2)}
                                </Typography>
                                {notification.data.percentage_change && (
                                  <Chip
                                    size="small"
                                    label={`${notification.data.percentage_change > 0 ? '+' : ''}${notification.data.percentage_change.toFixed(1)}%`}
                                    color={notification.data.percentage_change > 0 ? 'error' : 'success'}
                                    sx={{ height: 16, fontSize: '0.7rem' }}
                                  />
                                )}
                              </Box>
                            )}
                            
                            <Typography variant="caption" color="text.disabled">
                              {formatTimestamp(notification.timestamp)}
                            </Typography>
                          </Box>
                        }
                      />
                      
                      <ListItemSecondaryAction>
                        <IconButton
                          size="small"
                          onClick={(e) => {
                            e.stopPropagation();
                            clearNotification(notification.id);
                          }}
                        >
                          <CloseIcon fontSize="small" />
                        </IconButton>
                      </ListItemSecondaryAction>
                    </ListItem>
                    {index < notifications.length - 1 && <Divider />}
                  </React.Fragment>
                ))}
              </List>
            )}
          </Box>

          {/* Footer */}
          {notifications.length > 0 && (
            <Box sx={{ 
              p: 1.5, 
              borderTop: 1, 
              borderColor: 'divider',
              backgroundColor: theme.palette.grey[50],
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}>
              <Button
                size="small"
                color="error"
                onClick={clearAllNotifications}
                sx={{ textTransform: 'none' }}
              >
                Limpar todas
              </Button>
              
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                <SettingsIcon sx={{ fontSize: 16, color: 'text.disabled' }} />
                <Typography variant="caption" color="text.disabled">
                  {notifications.length} de 50
                </Typography>
              </Box>
            </Box>
          )}
        </Paper>
      </Popover>
    </>
  );
};

export default NotificationCenter; 