import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  TextField,
  Grid,
  InputAdornment,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Button,
  CircularProgress,
  Alert,
  Menu,
  ListItemIcon,
  ListItemText,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions
} from '@mui/material';
import {
  Search as SearchIcon,
  FilterList as FilterIcon,
  Close as CloseIcon,
  Refresh as RefreshIcon,
  GetApp as DownloadIcon,
  PictureAsPdf as PdfIcon,
  InsertDriveFile as CsvIcon,
  Description as ExcelIcon,
  Assessment as StatisticsIcon,
  Schedule as ScheduleIcon
} from '@mui/icons-material';
import { format } from 'date-fns';
import { logService } from '../../services/logs';

const SystemLogs = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalLogs, setTotalLogs] = useState(0);
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({
    startDate: '',
    endDate: '',
    level: '',
    category: '',
    userId: '',
    searchTerm: ''
  });

  // Estados para gerenciar menus e diálogos de relatórios
  const [exportMenuAnchor, setExportMenuAnchor] = useState(null);
  const [reportMenuAnchor, setReportMenuAnchor] = useState(null);
  const [showScheduleDialog, setShowScheduleDialog] = useState(false);
  const [scheduleForm, setScheduleForm] = useState({
    frequency: 'weekly',
    format: 'pdf',
    recipients: '',
    reportName: 'Relatório Periódico de Logs'
  });
  const [reportLoading, setReportLoading] = useState(false);
  const [reportMessage, setReportMessage] = useState({ type: '', text: '' });

  const fetchLogs = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      console.log('Buscando logs do sistema...');

      // Preparar os parâmetros da requisição
      const params = {
        skip: page * rowsPerPage,
        limit: rowsPerPage
      };

      // Adicionar filtros aos parâmetros se estiverem definidos
      if (filters.startDate) params.start_date = filters.startDate;
      if (filters.endDate) params.end_date = filters.endDate;
      if (filters.level) params.level = filters.level;
      if (filters.category) params.category = filters.category;
      if (filters.userId) params.user_id = filters.userId;
      if (filters.searchTerm) params.search_term = filters.searchTerm;

      // Usar o serviço dedicado para buscar os logs
      const data = await logService.getLogs(params);
      console.log('Dados recebidos:', data);

      setLogs(data.items || []);
      setTotalLogs(data.total || 0);
    } catch (error) {
      console.error('Erro ao buscar logs:', error);

      // Mensagens de erro mais detalhadas baseadas no tipo de erro
      let errorMessage = 'Erro ao carregar logs do sistema: ';

      if (error.message) {
        errorMessage += error.message;
      } else if (error.response) {
        // Se o servidor respondeu com um erro
        if (error.response.status === 403) {
          errorMessage += 'Você não tem permissão para acessar os logs do sistema.';
        } else if (error.response.status === 401) {
          errorMessage += 'Sessão expirada. Por favor, faça login novamente.';
        } else {
          errorMessage += `Erro do servidor: ${error.response.status} ${error.response.statusText}`;
        }
      } else {
        errorMessage += 'Erro de comunicação com o servidor. Verifique se o backend está em execução.';
      }

      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [page, rowsPerPage, filters]);

  useEffect(() => {
    fetchLogs();
  }, [fetchLogs]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleFilterChange = (event) => {
    const { name, value } = event.target;
    setFilters(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleApplyFilters = () => {
    setPage(0); // Reset para a primeira página ao aplicar filtros
    fetchLogs();
  };

  const handleClearFilters = () => {
    setFilters({
      startDate: '',
      endDate: '',
      level: '',
      category: '',
      userId: '',
      searchTerm: ''
    });
    setPage(0);
    fetchLogs();
  };

  const getLevelColor = (level) => {
    switch (level) {
      case 'HIGH':
        return 'error';
      case 'MEDIUM':
        return 'warning';
      case 'LOW':
        return 'info';
      default:
        return 'default';
    }
  };

  const getCategoryColor = (category) => {
    switch (category) {
      case 'SECURITY':
        return 'error';
      case 'SYSTEM':
        return 'primary';
      case 'USER':
        return 'success';
      case 'API':
        return 'warning';
      default:
        return 'default';
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return '';
    try {
      return format(new Date(dateString), 'dd/MM/yyyy HH:mm:ss');
    } catch (error) {
      return dateString;
    }
  };

  // Handlers para os menus de relatórios
  const handleExportMenuOpen = (event) => {
    setExportMenuAnchor(event.currentTarget);
  };

  const handleExportMenuClose = () => {
    setExportMenuAnchor(null);
  };

  const handleReportMenuOpen = (event) => {
    setReportMenuAnchor(event.currentTarget);
  };

  const handleReportMenuClose = () => {
    setReportMenuAnchor(null);
  };

  // Exportar logs em formato específico
  const handleExport = async (format) => {
    try {
      setReportLoading(true);
      setReportMessage({ type: '', text: '' });

      // Aplicar filtros atuais à exportação
      const params = { ...filters };
      await logService.exportLogsInFormat(format, params);

      setReportMessage({
        type: 'success',
        text: `Relatório exportado com sucesso em formato ${format.toUpperCase()}`
      });
    } catch (error) {
      console.error(`Erro ao exportar logs em formato ${format}:`, error);
      setReportMessage({
        type: 'error',
        text: `Erro ao exportar logs: ${error.message || 'Falha na exportação'}`
      });
    } finally {
      setReportLoading(false);
      handleExportMenuClose();
    }
  };

  // Gerar relatório estatístico
  const handleGenerateStatisticalReport = async () => {
    try {
      setReportLoading(true);
      setReportMessage({ type: '', text: '' });

      const data = await logService.generateStatisticalReport(filters);

      // Aqui você poderia exibir o relatório em um modal ou iniciar o download
      console.log('Relatório estatístico gerado:', data);

      setReportMessage({
        type: 'success',
        text: 'Relatório estatístico gerado com sucesso'
      });
    } catch (error) {
      console.error('Erro ao gerar relatório estatístico:', error);
      setReportMessage({
        type: 'error',
        text: `Erro ao gerar relatório: ${error.message || 'Falha na geração do relatório'}`
      });
    } finally {
      setReportLoading(false);
      handleReportMenuClose();
    }
  };

  // Abrir diálogo de agendamento
  const handleOpenScheduleDialog = () => {
    setShowScheduleDialog(true);
    handleReportMenuClose();
  };

  // Fechar diálogo de agendamento
  const handleCloseScheduleDialog = () => {
    setShowScheduleDialog(false);
  };

  // Atualizar formulário de agendamento
  const handleScheduleFormChange = (field, value) => {
    setScheduleForm(prev => ({
      ...prev,
      [field]: value
    }));
  };

  // Agendar relatório periódico
  const handleScheduleReport = async () => {
    try {
      setReportLoading(true);

      // Preparar destinatários (dividir string em array)
      const recipients = scheduleForm.recipients
        .split(',')
        .map(email => email.trim())
        .filter(email => email);

      const schedule = {
        ...scheduleForm,
        recipients,
        filters: { ...filters } // Incluir filtros atuais
      };

      await logService.schedulePeriodicReport(schedule);

      setReportMessage({
        type: 'success',
        text: 'Relatório agendado com sucesso'
      });
      handleCloseScheduleDialog();
    } catch (error) {
      console.error('Erro ao agendar relatório:', error);
      setReportMessage({
        type: 'error',
        text: `Erro ao agendar relatório: ${error.message || 'Falha no agendamento'}`
      });
    } finally {
      setReportLoading(false);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Logs do Sistema
      </Typography>

      {/* Banner para identificar a página */}
      <Paper
        elevation={3}
        sx={{
          p: 3,
          mb: 4,
          bgcolor: 'info.light',
          color: 'info.contrastText',
          borderLeft: '6px solid',
          borderColor: 'info.main',
          display: 'flex',
          flexDirection: 'column',
          gap: 1
        }}
      >
        <Typography variant="h5" fontWeight="bold">
          Logs do Sistema
        </Typography>
        <Typography variant="body1">
          Visualize e analise todos os registros de atividades do sistema. Você pode filtrar, pesquisar
          e exportar logs para auditoria e solução de problemas.
        </Typography>
      </Paper>

      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h4" component="h1" gutterBottom>
          Logs do Sistema
        </Typography>
        <Box>
          <IconButton
            color={showFilters ? "primary" : "default"}
            onClick={() => setShowFilters(!showFilters)}
            sx={{ mr: 1 }}
            title="Filtros"
          >
            <FilterIcon />
          </IconButton>
          <IconButton
            color="primary"
            onClick={() => fetchLogs()}
            sx={{ mr: 1 }}
            title="Atualizar"
          >
            <RefreshIcon />
          </IconButton>

          {/* Botão de Exportação com Menu */}
          <Button
            variant="outlined"
            color="primary"
            startIcon={<DownloadIcon />}
            onClick={handleExportMenuOpen}
            sx={{ mr: 1 }}
          >
            Exportar
          </Button>
          <Menu
            anchorEl={exportMenuAnchor}
            open={Boolean(exportMenuAnchor)}
            onClose={handleExportMenuClose}
          >
            <MenuItem onClick={() => handleExport('csv')}>
              <ListItemIcon>
                <CsvIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>CSV</ListItemText>
            </MenuItem>
            <MenuItem onClick={() => handleExport('excel')}>
              <ListItemIcon>
                <ExcelIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>Excel</ListItemText>
            </MenuItem>
            <MenuItem onClick={() => handleExport('pdf')}>
              <ListItemIcon>
                <PdfIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>PDF</ListItemText>
            </MenuItem>
          </Menu>

          {/* Botão de Relatórios com Menu */}
          <Button
            variant="contained"
            color="primary"
            startIcon={<StatisticsIcon />}
            onClick={handleReportMenuOpen}
          >
            Relatórios
          </Button>
          <Menu
            anchorEl={reportMenuAnchor}
            open={Boolean(reportMenuAnchor)}
            onClose={handleReportMenuClose}
          >
            <MenuItem onClick={handleGenerateStatisticalReport}>
              <ListItemIcon>
                <StatisticsIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>Relatório Estatístico</ListItemText>
            </MenuItem>
            <MenuItem onClick={handleOpenScheduleDialog}>
              <ListItemIcon>
                <ScheduleIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText>Agendar Relatório</ListItemText>
            </MenuItem>
          </Menu>
        </Box>
      </Box>

      {/* Mensagem de feedback para operações de relatório */}
      {reportMessage.text && (
        <Alert
          severity={reportMessage.type}
          sx={{ mb: 2 }}
          onClose={() => setReportMessage({ type: '', text: '' })}
        >
          {reportMessage.text}
        </Alert>
      )}

      {/* Indicador de carregamento para operações de relatório */}
      {reportLoading && (
        <Box display="flex" justifyContent="center" alignItems="center" mb={2}>
          <CircularProgress size={24} sx={{ mr: 1 }} />
          <Typography>Processando relatório...</Typography>
        </Box>
      )}

      {showFilters && (
        <Paper elevation={3} sx={{ p: 2, mb: 3 }}>
          <Typography variant="h6" gutterBottom>Filtros</Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} md={6} lg={3}>
              <TextField
                label="Data Inicial"
                type="datetime-local"
                name="startDate"
                value={filters.startDate}
                onChange={handleFilterChange}
                fullWidth
                variant="outlined"
                size="small"
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} md={6} lg={3}>
              <TextField
                label="Data Final"
                type="datetime-local"
                name="endDate"
                value={filters.endDate}
                onChange={handleFilterChange}
                fullWidth
                variant="outlined"
                size="small"
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} md={6} lg={2}>
              <FormControl fullWidth size="small">
                <InputLabel id="level-select-label">Nível</InputLabel>
                <Select
                  labelId="level-select-label"
                  id="level-select"
                  name="level"
                  value={filters.level}
                  label="Nível"
                  onChange={handleFilterChange}
                  variant="outlined"
                >
                  <MenuItem value="">Todos</MenuItem>
                  <MenuItem value="HIGH">Alto</MenuItem>
                  <MenuItem value="MEDIUM">Médio</MenuItem>
                  <MenuItem value="LOW">Baixo</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6} lg={2}>
              <FormControl fullWidth size="small">
                <InputLabel id="category-select-label">Categoria</InputLabel>
                <Select
                  labelId="category-select-label"
                  id="category-select"
                  name="category"
                  value={filters.category}
                  label="Categoria"
                  onChange={handleFilterChange}
                  variant="outlined"
                >
                  <MenuItem value="">Todas</MenuItem>
                  <MenuItem value="SECURITY">Segurança</MenuItem>
                  <MenuItem value="SYSTEM">Sistema</MenuItem>
                  <MenuItem value="USER">Usuário</MenuItem>
                  <MenuItem value="API">API</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6} lg={2}>
              <TextField
                fullWidth
                size="small"
                label="ID do Usuário"
                name="userId"
                value={filters.userId}
                onChange={handleFilterChange}
                variant="outlined"
                type="number"
              />
            </Grid>
            <Grid item xs={12} md={6} lg={4}>
              <TextField
                fullWidth
                size="small"
                label="Termo de Busca"
                name="searchTerm"
                value={filters.searchTerm}
                onChange={handleFilterChange}
                variant="outlined"
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <SearchIcon />
                    </InputAdornment>
                  ),
                }}
              />
            </Grid>
            <Grid item xs={12} md={12} lg={8} display="flex" justifyContent="flex-end">
              <Button
                variant="outlined"
                onClick={handleClearFilters}
                startIcon={<CloseIcon />}
                sx={{ mr: 1 }}
              >
                Limpar
              </Button>
              <Button
                variant="contained"
                onClick={handleApplyFilters}
                startIcon={<FilterIcon />}
              >
                Aplicar Filtros
              </Button>
            </Grid>
          </Grid>
        </Paper>
      )}

      <Paper elevation={3}>
        {loading && (
          <Box display="flex" justifyContent="center" alignItems="center" p={2}>
            <CircularProgress />
          </Box>
        )}
        {error && (
          <Box p={2}>
            <Alert severity="error">{error}</Alert>
          </Box>
        )}
        {!loading && !error && (
          <>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>ID</TableCell>
                    <TableCell>Timestamp</TableCell>
                    <TableCell>Nível</TableCell>
                    <TableCell>Categoria</TableCell>
                    <TableCell>Ação</TableCell>
                    <TableCell>Descrição</TableCell>
                    <TableCell>IP</TableCell>
                    <TableCell>Usuário</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {logs.map((log) => (
                    <TableRow key={log.id}>
                      <TableCell>{log.id}</TableCell>
                      <TableCell>{formatDate(log.timestamp)}</TableCell>
                      <TableCell>
                        <Chip
                          label={log.level}
                          color={getLevelColor(log.level)}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={log.category}
                          color={getCategoryColor(log.category)}
                        />
                      </TableCell>
                      <TableCell>{log.action}</TableCell>
                      <TableCell sx={{ maxWidth: 300 }}>{log.description}</TableCell>
                      <TableCell>{log.ip_address}</TableCell>
                      <TableCell>{log.user_email}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
            <TablePagination
              rowsPerPageOptions={[5, 10, 25, 50]}
              component="div"
              count={totalLogs}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
            />
          </>
        )}
      </Paper>

      {/* Dialog for scheduling reports */}
      <Dialog open={showScheduleDialog} onClose={handleCloseScheduleDialog}>
        <DialogTitle>Agendar Relatório</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Configure o agendamento do relatório periódico.
          </DialogContentText>
          <Box sx={{ mt: 2 }}>
            <FormControl fullWidth sx={{ mb: 2 }}>
              <InputLabel>Frequência</InputLabel>
              <Select
                value={scheduleForm.frequency}
                label="Frequência"
                onChange={(e) => handleScheduleFormChange('frequency', e.target.value)}
                variant="outlined"
              >
                <MenuItem value="daily">Diário</MenuItem>
                <MenuItem value="weekly">Semanal</MenuItem>
                <MenuItem value="monthly">Mensal</MenuItem>
              </Select>
            </FormControl>
            <FormControl fullWidth sx={{ mb: 2 }}>
              <InputLabel>Formato</InputLabel>
              <Select
                value={scheduleForm.format}
                label="Formato"
                onChange={(e) => handleScheduleFormChange('format', e.target.value)}
                variant="outlined"
              >
                <MenuItem value="pdf">PDF</MenuItem>
                <MenuItem value="excel">Excel</MenuItem>
                <MenuItem value="csv">CSV</MenuItem>
              </Select>
            </FormControl>
            <TextField
              fullWidth
              label="Nome do Relatório"
              value={scheduleForm.reportName}
              onChange={(e) => handleScheduleFormChange('reportName', e.target.value)}
              sx={{ mb: 2 }}
              variant="outlined"
            />
            <TextField
              fullWidth
              label="Destinatários (separados por vírgula)"
              value={scheduleForm.recipients}
              onChange={(e) => handleScheduleFormChange('recipients', e.target.value)}
              helperText="Ex: email1@example.com, email2@example.com"
              variant="outlined"
              multiline
              rows={2}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseScheduleDialog}>Cancelar</Button>
          <Button onClick={handleScheduleReport} variant="contained" color="primary">
            Agendar
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default SystemLogs;
