import React, { useState, useEffect } from 'react';
import {
  Card,
  CardContent,
  CardHeader,
  Typography,
  Box,
  Alert,
  Slider,
  Switch,
  FormControlLabel,
  Button,
  Divider,
  Grid,
  Chip,
  CircularProgress,
  Stack,
  Snackbar
} from '@mui/material';
import {
  Security,
  Save,
  Refresh,
  NotificationImportant,
  AutorenewRounded,
  Email
} from '@mui/icons-material';
import { get, post } from '../../services/api';

const AntiFalsificationSettings = () => {
  const [threshold, setThreshold] = useState(30);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [refreshInterval, setRefreshInterval] = useState(300);
  const [emailNotifications, setEmailNotifications] = useState(true);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [statistics, setStatistics] = useState({});

  useEffect(() => {
    loadSettings();
    loadStatistics();
  }, []);

  const loadSettings = async () => {
    try {
      setLoading(true);

      // Carregar threshold
      const thresholdResponse = await get('/api/settings/suspicious-threshold');
      if (thresholdResponse.data && thresholdResponse.data.success) {
        setThreshold(thresholdResponse.data.threshold_percentage);
      }

      // Carregar outras configurações
      const settingsResponse = await get('/api/settings/suspicious-products');
      if (settingsResponse.data && settingsResponse.data.success) {
        const settings = settingsResponse.data.data;
        setAutoRefresh(settings.auto_refresh || false);
        setRefreshInterval(settings.refresh_interval || 300);
        setEmailNotifications(settings.email_notifications || true);
      }
    } catch (error) {
      console.error('Erro ao carregar configurações:', error);
      setError('Erro ao carregar configurações');
    } finally {
      setLoading(false);
    }
  };

  const loadStatistics = async () => {
    try {
      const response = await get('/api/suspicious-products/statistics', {
        days_back: 30
      });
      if (response.data && response.data.success) {
        setStatistics(response.data.data);
      }
    } catch (error) {
      console.error('Erro ao carregar estatísticas:', error);
    }
  };

  const saveSettings = async () => {
    try {
      setSaving(true);

      // Salvar threshold
      await post(`/api/settings/suspicious-threshold?threshold=${threshold}`);

      // Salvar outras configurações
      await post('/api/settings/suspicious-products', {
        auto_refresh: autoRefresh,
        refresh_interval: refreshInterval,
        email_notifications: emailNotifications
      });

      setSuccess('Configurações salvas com sucesso!');
      loadStatistics(); // Recarregar estatísticas após mudança no threshold
    } catch (error) {
      console.error('Erro ao salvar configurações:', error);
      setError('Erro ao salvar configurações');
    } finally {
      setSaving(false);
    }
  };

  const resetToDefaults = () => {
    setThreshold(30);
    setAutoRefresh(false);
    setRefreshInterval(300);
    setEmailNotifications(true);
  };

  const getThresholdImpact = () => {
    if (threshold <= 15) {
      return {
        level: 'high',
        color: 'error',
        message: 'Muito sensível - pode gerar muitos falsos positivos'
      };
    } else if (threshold <= 25) {
      return {
        level: 'medium',
        color: 'warning',
        message: 'Sensibilidade média - balanceado'
      };
    } else if (threshold <= 40) {
      return {
        level: 'low',
        color: 'success',
        message: 'Recomendado para produtos HP originais'
      };
    } else {
      return {
        level: 'very-low',
        color: 'info',
        message: 'Pouco sensível - pode perder algumas detecções'
      };
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
          <CircularProgress />
        </CardContent>
      </Card>
    );
  }

  const impact = getThresholdImpact();

  return (
    <Card>
      <CardHeader
        avatar={<Security color="primary" />}
        title="Sistema Anti-Falsificação"
        subheader="Configurações de detecção de produtos suspeitos"
        action={
          <Button
            variant="outlined"
            startIcon={<Refresh />}
            onClick={loadStatistics}
            size="small"
          >
            Atualizar
          </Button>
        }
      />
      <CardContent>
        {error && (
          <Alert severity="error" sx={{ mb: 3 }}>
            {error}
          </Alert>
        )}

        {/* Estatísticas atuais */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Estatísticas Atuais (30 dias)
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={6} md={3}>
              <Box sx={{ textAlign: 'center', p: 2, border: 1, borderColor: 'divider', borderRadius: 1 }}>
                <NotificationImportant color="error" />
                <Typography variant="h6" color="error.main">
                  {statistics.total_suspicious || 0}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  Total Detectados
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={6} md={3}>
              <Box sx={{ textAlign: 'center', p: 2, border: 1, borderColor: 'divider', borderRadius: 1 }}>
                <Typography variant="h6" color="success.main">
                  {statistics.by_status?.FALSE_POSITIVE || 0}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  Falsos Positivos
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={6} md={3}>
              <Box sx={{ textAlign: 'center', p: 2, border: 1, borderColor: 'divider', borderRadius: 1 }}>
                <Typography variant="h6" color="error.main">
                  {statistics.by_status?.CONFIRMED || 0}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  Confirmados
                </Typography>
              </Box>
            </Grid>
            <Grid item xs={6} md={3}>
              <Box sx={{ textAlign: 'center', p: 2, border: 1, borderColor: 'divider', borderRadius: 1 }}>
                <Typography variant="h6" color="primary.main">
                  {statistics.total_suspicious ?
                    Math.round(((statistics.by_status?.CONFIRMED || 0) / statistics.total_suspicious) * 100) : 0}%
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  Taxa de Precisão
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </Box>

        <Divider sx={{ my: 3 }} />

        {/* Configuração de Threshold */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Threshold de Detecção
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Define a diferença percentual mínima no preço para considerar um produto suspeito
          </Typography>

          <Box sx={{ px: 2, mb: 2 }}>
            <Typography gutterBottom>
              Threshold Atual: <strong>{threshold}%</strong>
            </Typography>
            <Slider
              value={threshold}
              onChange={(_, value) => setThreshold(value)}
              min={5}
              max={80}
              step={5}
              marks={[
                { value: 10, label: '10%' },
                { value: 20, label: '20%' },
                { value: 30, label: '30%' },
                { value: 50, label: '50%' },
                { value: 70, label: '70%' }
              ]}
              valueLabelDisplay="auto"
            />
          </Box>

          <Alert severity={impact.color} sx={{ mb: 2 }}>
            <Typography variant="body2">
              <strong>Impacto:</strong> {impact.message}
            </Typography>
          </Alert>

          <Typography variant="body2" color="text.secondary">
            Produtos com preços <strong>{threshold}% ou mais</strong> abaixo do valor de referência
            serão marcados como suspeitos de falsificação.
          </Typography>
        </Box>

        <Divider sx={{ my: 3 }} />

        {/* Configurações de Automação */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Automação e Monitoramento
          </Typography>

          <Stack spacing={3}>
            <FormControlLabel
              control={
                <Switch
                  checked={autoRefresh}
                  onChange={(e) => setAutoRefresh(e.target.checked)}
                />
              }
              label={
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <AutorenewRounded fontSize="small" />
                  Atualização automática de dados
                </Box>
              }
            />

            {autoRefresh && (
              <Box sx={{ ml: 4 }}>
                <Typography gutterBottom>
                  Intervalo: {Math.floor(refreshInterval / 60)} minutos
                </Typography>
                <Slider
                  value={refreshInterval}
                  onChange={(_, value) => setRefreshInterval(value)}
                  min={60}
                  max={3600}
                  step={60}
                  marks={[
                    { value: 60, label: '1min' },
                    { value: 300, label: '5min' },
                    { value: 900, label: '15min' },
                    { value: 1800, label: '30min' },
                    { value: 3600, label: '1h' }
                  ]}
                  valueLabelDisplay="auto"
                  valueLabelFormat={(value) => `${Math.floor(value / 60)}min`}
                />
              </Box>
            )}

            <FormControlLabel
              control={
                <Switch
                  checked={emailNotifications}
                  onChange={(e) => setEmailNotifications(e.target.checked)}
                />
              }
              label={
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Email fontSize="small" />
                  Notificações por e-mail
                </Box>
              }
            />
          </Stack>
        </Box>

        <Divider sx={{ my: 3 }} />

        {/* Recomendações */}
        <Alert severity="info" sx={{ mb: 3 }}>
          <Typography variant="body2">
            <strong>Recomendações:</strong>
            <br />
            • Para cartuchos HP originais: 25-35% de threshold
            <br />
            • Para monitoramento intensivo: ativar auto-refresh a cada 5-15 minutos
            <br />
            • Revise regularmente os falsos positivos para ajustar o threshold
          </Typography>
        </Alert>

        {/* Botões de ação */}
        <Stack direction="row" spacing={2} justifyContent="flex-end">
          <Button
            variant="outlined"
            onClick={resetToDefaults}
            disabled={saving}
          >
            Restaurar Padrões
          </Button>
          <Button
            variant="contained"
            startIcon={saving ? <CircularProgress size={20} /> : <Save />}
            onClick={saveSettings}
            disabled={saving}
          >
            {saving ? 'Salvando...' : 'Salvar Configurações'}
          </Button>
        </Stack>
      </CardContent>

      {/* Snackbar para mensagens de sucesso */}
      <Snackbar
        open={!!success}
        autoHideDuration={6000}
        onClose={() => setSuccess(null)}
        message={success}
      />
    </Card>
  );
};

export default AntiFalsificationSettings;
