import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Box,
  Tabs,
  Tab,
  Alert,
  Button,
  CircularProgress
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import {
  Settings as SettingsIcon,
  Storage as StorageIcon,
  Security as SecurityIcon,
  History as HistoryIcon,
  Api as ApiIcon,
  VpnKey as VpnKeyIcon,
  PersonAdd as PersonAddIcon,
  Notifications as NotificationsIcon
} from '@mui/icons-material';
import { useAuth } from '../hooks/useAuth';
import AntiFalsificationSettings from '../components/Settings/AntiFalsificationSettings';
import SystemLogs from '../components/Settings/SystemLogs';
import RawScrapingData from '../components/Settings/RawScrapingData';

// Importações das configurações existentes
import ApiSettings from './Settings/ApiSettings';
import ApiKeySettings from './Settings/ApiKeySettings';
import UserManagement from './Settings/UserApproval';
import SystemSettings from './Settings/SystemSettings';
import NotificationSettings from './Settings/NotificationSettings';

// Componente para exibir o conteúdo da aba
function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`settings-tabpanel-${index}`}
      aria-labelledby={`settings-tab-${index}`}
      style={{ paddingTop: '1rem' }}
      {...other}
    >
      {value === index && (
        <Box>
          {children}
        </Box>
      )}
    </div>
  );
}

function a11yProps(index) {
  return {
    id: `settings-tab-${index}`,
    'aria-controls': `settings-tabpanel-${index}`,
  };
}

// Componente principal de Configurações
const Settings = () => {
  const [tabIndex, setTabIndex] = useState(0);
  const [userData, setUserData] = useState(null);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();
  const navigate = useNavigate();

  // Função para mudar de aba
  const handleTabChange = (event, newValue) => {
    setTabIndex(newValue);
  };

  // Efeito para verificar permissões do usuário usando o hook useAuth
  useEffect(() => {
    try {
      setLoading(true);

      if (user) {
        // Definir manualmente o usuário sistemas@smstecnologia.com.br como superusuário
        // independentemente das permissões do banco de dados
        if (user.email === 'sistemas@smstecnologia.com.br') {
          const superUser = {
            ...user,
            role: 'admin',
            is_superuser: true
          };
          setUserData(superUser);
          setIsAuthorized(true);
          console.log('Usuário sistemas@smstecnologia.com.br elevado a superusuário manualmente no frontend');
        } else {
          setUserData(user);

          // Verificar se o usuário é administrador
          const isAdmin = user.is_superuser === true || user.role === 'admin';
          setIsAuthorized(isAdmin);
        }
      } else {
        setIsAuthorized(false);
      }
    } catch (error) {
      console.error('Erro ao verificar permissões:', error);
      setIsAuthorized(false);
    } finally {
      setLoading(false);
    }
  }, [user]);

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4 }}>
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 10 }}>
          <CircularProgress />
        </Box>
      </Container>
    );
  }

  if (!isAuthorized) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4 }}>
        <Alert severity="warning" sx={{ mb: 3 }}>
          Você não possui permissões de administrador para acessar estas configurações.
        </Alert>
        <Button variant="contained" onClick={() => navigate('/dashboard')}>
          Voltar para o Dashboard
        </Button>
      </Container>
    );
  }

  return (
    <Container maxWidth="xl" sx={{ py: 4 }}>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" component="h1" fontWeight="bold" gutterBottom>
          Configurações do Sistema
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Gerencie as configurações e visualize dados do sistema
        </Typography>
      </Box>

      {/* Abas de configuração */}
      <Paper sx={{ boxShadow: 2 }}>
        <Tabs
          value={tabIndex}
          onChange={handleTabChange}
          variant="scrollable"
          scrollButtons="auto"
          sx={{
            borderBottom: 1,
            borderColor: 'divider',
            backgroundColor: 'background.paper',
          }}
        >
          <Tab
            icon={<ApiIcon fontSize="small" />}
            iconPosition="start"
            label="API OpenAI"
            {...a11yProps(0)}
          />
          <Tab
            icon={<VpnKeyIcon fontSize="small" />}
            iconPosition="start"
            label="Chaves API"
            {...a11yProps(1)}
          />
          <Tab
            icon={<PersonAddIcon fontSize="small" />}
            iconPosition="start"
            label="Aprovação de Usuários"
            {...a11yProps(2)}
          />
          <Tab
            icon={<SettingsIcon fontSize="small" />}
            iconPosition="start"
            label="Configurações do Sistema"
            {...a11yProps(3)}
          />
          <Tab
            icon={<NotificationsIcon fontSize="small" />}
            iconPosition="start"
            label="Notificações"
            {...a11yProps(4)}
          />
          <Tab
            icon={<SecurityIcon fontSize="small" />}
            iconPosition="start"
            label="Sistema Anti-Falsificação"
            {...a11yProps(5)}
          />
          <Tab
            icon={<StorageIcon fontSize="small" />}
            iconPosition="start"
            label="Dados Brutos"
            {...a11yProps(6)}
          />
          <Tab
            icon={<HistoryIcon fontSize="small" />}
            iconPosition="start"
            label="Logs do Sistema"
            {...a11yProps(7)}
          />
        </Tabs>

        {/* Conteúdo das abas */}
        <Box sx={{ p: { xs: 2, md: 3 } }}>
          {/* Abas existentes */}
          <TabPanel value={tabIndex} index={0}>
            <ApiSettings />
          </TabPanel>

          <TabPanel value={tabIndex} index={1}>
            <ApiKeySettings />
          </TabPanel>

          <TabPanel value={tabIndex} index={2}>
            <UserManagement />
          </TabPanel>

          <TabPanel value={tabIndex} index={3}>
            <SystemSettings />
          </TabPanel>

          <TabPanel value={tabIndex} index={4}>
            <NotificationSettings />
          </TabPanel>

          {/* Abas adicionadas recentemente */}
          <TabPanel value={tabIndex} index={5}>
            <AntiFalsificationSettings />
          </TabPanel>

          {/* Nova aba: Dados Brutos */}
          <TabPanel value={tabIndex} index={6}>
            <RawScrapingData />
          </TabPanel>

          {/* Aba: Logs do Sistema */}
          <TabPanel value={tabIndex} index={7}>
            <SystemLogs />
          </TabPanel>
        </Box>
      </Paper>
    </Container>
  );
};

export default Settings;
