import { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Grid,
  Button,
  CircularProgress,
  TextField,
  Switch,
  FormControlLabel,
  Divider,
  Alert,
  Paper,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Select,
  MenuItem,
  FormControl,
  InputLabel
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SaveIcon from '@mui/icons-material/Save';
import SettingsIcon from '@mui/icons-material/Settings';
import BackupIcon from '@mui/icons-material/Backup';
import RestoreIcon from '@mui/icons-material/Restore';
import { useAuth } from '../../../hooks/useAuth';
import { useAppTheme } from '../../../contexts/ThemeContext';

const SystemSettings = () => {
  const { token: authToken, user } = useAuth();
  const { themeMode, changeTheme } = useAppTheme();
  const [loading, setLoading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [error, setError] = useState(null);

  // Estado para configurações do sistema
  const [settings, setSettings] = useState({
    maintenanceMode: false,
    debugMode: false,
    logLevel: 'info',
    maxProductsPerUser: 50,
    maxApiRequestsPerDay: 1000,
    emailNotifications: true,
    autoBackupEnabled: true,
    autoBackupInterval: 'daily',
    theme: 'light',
    // Configurações de Scraping Automático
    scrapingEnabled: true,
    scrapingMode: 'interval', // 'interval' ou 'schedule'
    scrapingInterval: 6, // 6, 12 ou 24 horas
    scrapingTime: '08:00', // Horário específico (HH:mm)
    scrapingRetryOnError: true,
    scrapingMaxRetries: 3,
    scrapingLastRun: null,
    scrapingNextRun: null
  });

  // Carregar configurações
  useEffect(() => {
    const fetchSettings = async () => {
      setLoading(true);
      try {
        const token = localStorage.getItem('token') || authToken;
        if (!token) {
          setError('Sessão expirada. Por favor, faça login novamente.');
          setLoading(false);
          return;
        }

        // Buscar configurações do sistema
        try {
          const response = await fetch('/api/settings/', {
            method: 'GET',
            headers: {
              'Authorization': `Bearer ${token}`,
              'Content-Type': 'application/json'
            }
          });

          if (response.ok) {
            const systemSettings = await response.json();
            
            // Atualizar settings com dados do backend
            setSettings(prev => ({
              ...prev,
              ...systemSettings
            }));
          }
        } catch (settingsError) {
          console.warn('Configurações do sistema não encontradas, usando padrões:', settingsError);
        }

        // Buscar status do scraping
        try {
          const scrapingResponse = await fetch('/api/settings/scraping/status', {
            method: 'GET',
            headers: {
              'Authorization': `Bearer ${token}`
            }
          });

          if (scrapingResponse.ok) {
            const scrapingStatus = await scrapingResponse.json();
            
            // Atualizar configurações de scraping
            setSettings(prev => ({
              ...prev,
              scrapingEnabled: scrapingStatus.config?.enabled || false,
              scrapingMode: scrapingStatus.config?.mode || 'interval',
              scrapingInterval: scrapingStatus.config?.interval || 6,
              scrapingTime: scrapingStatus.config?.time || '08:00',
              scrapingRetryOnError: scrapingStatus.config?.retryOnError || true,
              scrapingMaxRetries: scrapingStatus.config?.maxRetries || 3,
              scrapingLastRun: scrapingStatus.last_run,
              scrapingNextRun: scrapingStatus.next_execution
            }));
          }
        } catch (scrapingError) {
          console.warn('Status do scraping não disponível:', scrapingError);
        }

      } catch (err) {
        console.error('Erro ao carregar configurações do sistema:', err);
        setError('Não foi possível carregar as configurações. Usando configurações padrão.');
      } finally {
        setLoading(false);
      }
    };

    fetchSettings();
  }, [authToken]);

  // Atualizar configurações
  const handleChange = (e) => {
    const { name, value, checked } = e.target;
    setSettings(prev => ({
      ...prev,
      [name]: e.target.type === 'checkbox' ? checked : value
    }));
  };

  // Salvar configurações
  const handleSaveSettings = async () => {
    setLoading(true);
    setSaveSuccess(false);

    try {
      const token = localStorage.getItem('token') || authToken;
      if (!token) {
        setError('Sessão expirada. Por favor, faça login novamente.');
        setLoading(false);
        return;
      }

      // Chamada real à API para salvar as configurações
      const response = await fetch('/api/settings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(settings)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Erro ao salvar configurações');
      }

      const result = await response.json();
      
      // Salvar configurações específicas de scraping
      const scrapingSettings = {
        enabled: settings.scrapingEnabled,
        mode: settings.scrapingMode,
        interval: settings.scrapingInterval,
        time: settings.scrapingTime,
        retryOnError: settings.scrapingRetryOnError,
        maxRetries: settings.scrapingMaxRetries
      };

      // Chamar API específica para configurações de scraping
      const scrapingResponse = await fetch('/api/settings/scraping', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(scrapingSettings)
      });

      if (!scrapingResponse.ok) {
        const scrapingError = await scrapingResponse.json();
        throw new Error(scrapingError.detail || 'Erro ao salvar configurações de coleta');
      }

      setSaveSuccess(true);
      
      // Limpar mensagem de sucesso após 3 segundos
      setTimeout(() => setSaveSuccess(false), 3000);

    } catch (err) {
      console.error('Erro ao salvar configurações do sistema:', err);
      setError(err.message || 'Não foi possível salvar as configurações. Por favor, tente novamente.');
    } finally {
      setLoading(false);
    }
  };

  // Backup do sistema
  const handleCreateBackup = async () => {
    setLoading(true);
    try {
      // Simulação de backup
      setTimeout(() => {
        setLoading(false);
        setSaveSuccess(true);
        setTimeout(() => setSaveSuccess(false), 3000);
      }, 1500);
    } catch (err) {
      setError('Erro ao criar backup do sistema');
      setLoading(false);
    }
  };

  // Forçar execução imediata do scraping
  const handleForceScrapingExecution = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token') || authToken;
      if (!token) {
        setError('Sessão expirada. Por favor, faça login novamente.');
        setLoading(false);
        return;
      }

      // Tentar primeiro o endpoint público (modo desenvolvimento)
      let response;
      try {
        response = await fetch('/api/settings/scraping/execute-public', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' }
        });
      } catch (publicErr) {
        console.warn('Endpoint público falhou, tentando endpoint autenticado:', publicErr);
        try {
          response = await fetch('/api/settings/scraping/execute', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`
            }
          });
        } catch (authErr) {
          console.warn('Endpoint autenticado falhou, tentando fallback final:', authErr);
          try {
            response = await fetch('/api/scraping/start', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' }
            });
          } catch (finalErr) {
            console.warn('Todos os endpoints falharam:', finalErr);
            response = new Response(JSON.stringify({ detail: 'Todos os endpoints de scraping falharam' }), { status: 500, headers: { 'Content-Type': 'application/json' } });
          }
        }
      }

      if (!response.ok) {
        let errorMessage = 'Erro ao executar scraping';
        try {
          const errorData = await response.json();
          errorMessage = errorData.detail || errorMessage;
        } catch (_) {
          console.warn('Não foi possível ler o corpo da resposta de erro ao executar scraping');
        }
        throw new Error(errorMessage);
      }

      const result = await response.json();
      
      if (result.success) {
        setSaveSuccess(true);
        setSettings(prev => ({
          ...prev,
          scrapingLastRun: new Date().toISOString()
        }));
      } else {
        // Mostrar mensagem informativa em vez de erro quando é apenas desabilitado
        setError(result.message || 'Funcionalidade temporariamente indisponível');
      }

      // Limpar mensagem após 5 segundos
      setTimeout(() => {
        setSaveSuccess(false);
        setError(null);
      }, 5000);

    } catch (err) {
      console.error('Erro ao forçar execução do scraping:', err);
      setError(err.message || 'Não foi possível executar o scraping. Tente novamente.');
    } finally {
      setLoading(false);
    }
  };

  // Atualizar status do scraping
  const handleRefreshScrapingStatus = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token') || authToken;
      if (!token) {
        setError('Sessão expirada. Por favor, faça login novamente.');
        setLoading(false);
        return;
      }

      const response = await fetch('/api/settings/scraping/status', {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Erro ao buscar status');
      }

      const status = await response.json();
      
      // Atualizar configurações com o status atual
      setSettings(prev => ({
        ...prev,
        scrapingEnabled: status.config?.enabled || false,
        scrapingMode: status.config?.mode || 'interval',
        scrapingInterval: status.config?.interval || 6,
        scrapingTime: status.config?.time || '08:00',
        scrapingRetryOnError: status.config?.retryOnError || true,
        scrapingMaxRetries: status.config?.maxRetries || 3,
        scrapingLastRun: status.last_run,
        scrapingNextRun: status.next_execution
      }));

    } catch (err) {
      console.error('Erro ao atualizar status do scraping:', err);
      setError(err.message || 'Não foi possível atualizar o status.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Configurações do Sistema
      </Typography>

      {/* Banner para identificar a página */}
      <Paper
        elevation={3}
        sx={{
          p: 3,
          mb: 4,
          bgcolor: 'primary.light',
          color: 'primary.contrastText',
          borderLeft: '6px solid',
          borderColor: 'primary.main',
          display: 'flex',
          flexDirection: 'column',
          gap: 1
        }}
      >
        <Typography variant="h5" fontWeight="bold">
          Configurações Gerais
        </Typography>
        <Typography variant="body1">
          Gerencie as configurações globais do sistema, incluindo modo de manutenção,
          limites operacionais e configurações de backup.
        </Typography>
      </Paper>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {saveSuccess && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSaveSuccess(false)}>
          Configurações salvas com sucesso!
        </Alert>
      )}

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <Grid container spacing={3}>
          {/* Configurações gerais */}
          <Grid item xs={12}>
            <Accordion defaultExpanded>
              <AccordionSummary
                expandIcon={<ExpandMoreIcon />}
                aria-controls="panel1a-content"
                id="panel1a-header"
              >
                <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center' }}>
                  <SettingsIcon sx={{ mr: 1 }} /> Configurações Gerais
                </Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.maintenanceMode}
                          onChange={handleChange}
                          name="maintenanceMode"
                          color="warning"
                        />
                      }
                      label="Modo de Manutenção"
                    />
                    <Typography variant="caption" color="text.secondary" display="block">
                      Quando ativado, o sistema ficará indisponível para usuários normais
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.debugMode}
                          onChange={handleChange}
                          name="debugMode"
                          color="primary"
                        />
                      }
                      label="Modo de Depuração"
                    />
                    <Typography variant="caption" color="text.secondary" display="block">
                      Ativa logs detalhados para ajudar na resolução de problemas
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth sx={{ mt: 2 }}>
                      <InputLabel>Nível de Logs</InputLabel>
                      <Select
                        name="logLevel"
                        value={settings.logLevel}
                        label="Nível de Logs"
                        onChange={handleChange}
                      >
                        <MenuItem value="error">Apenas Erros</MenuItem>
                        <MenuItem value="warn">Avisos e Erros</MenuItem>
                        <MenuItem value="info">Informações</MenuItem>
                        <MenuItem value="debug">Detalhado (Debug)</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth sx={{ mt: 2 }}>
                      <InputLabel>Tema do Sistema</InputLabel>
                      <Select
                        name="theme"
                        value={themeMode}
                        label="Tema do Sistema"
                        onChange={(e) => {
                          changeTheme(e.target.value);
                          setSettings(prev => ({ ...prev, theme: e.target.value }));
                        }}
                      >
                        <MenuItem value="light">Claro</MenuItem>
                        <MenuItem value="dark">Escuro</MenuItem>
                        <MenuItem value="system">Automático (Baseado no sistema)</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                </Grid>
              </AccordionDetails>
            </Accordion>
          </Grid>

          {/* Limites e Restrições */}
          <Grid item xs={12}>
            <Accordion>
              <AccordionSummary
                expandIcon={<ExpandMoreIcon />}
                aria-controls="panel2a-content"
                id="panel2a-header"
              >
                <Typography variant="h6">Limites e Restrições</Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      label="Máximo de Produtos por Usuário"
                      type="number"
                      name="maxProductsPerUser"
                      value={settings.maxProductsPerUser}
                      onChange={handleChange}
                      InputProps={{ inputProps: { min: 1 } }}
                    />
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      Quantidade máxima de produtos que cada usuário pode rastrear
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      label="Máximo de Requisições de API por Dia"
                      type="number"
                      name="maxApiRequestsPerDay"
                      value={settings.maxApiRequestsPerDay}
                      onChange={handleChange}
                      InputProps={{ inputProps: { min: 100 } }}
                    />
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      Limite diário de requisições à API por usuário
                    </Typography>
                  </Grid>
                </Grid>
              </AccordionDetails>
            </Accordion>
          </Grid>

          {/* Configurações de Scraping Automático */}
          <Grid item xs={12}>
            <Accordion>
              <AccordionSummary
                expandIcon={<ExpandMoreIcon />}
                aria-controls="panel3a-content"
                id="panel3a-header"
              >
                <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center' }}>
                  <SettingsIcon sx={{ mr: 1 }} /> Coleta Automática de Dados
                </Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.scrapingEnabled}
                          onChange={handleChange}
                          name="scrapingEnabled"
                          color="primary"
                        />
                      }
                      label="Coleta Automática Ativada"
                    />
                    <Typography variant="caption" color="text.secondary" display="block">
                      Realiza coleta automática de preços dos produtos cadastrados no sistema
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>Modo de Execução</InputLabel>
                      <Select
                        name="scrapingMode"
                        value={settings.scrapingMode}
                        label="Modo de Execução"
                        onChange={handleChange}
                        disabled={!settings.scrapingEnabled}
                      >
                        <MenuItem value="interval">Por Intervalo</MenuItem>
                        <MenuItem value="schedule">Horário Específico</MenuItem>
                      </Select>
                    </FormControl>
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      Escolha entre execução por intervalo ou em horário específico
                    </Typography>
                  </Grid>

                  {settings.scrapingMode === 'interval' && (
                    <Grid item xs={12} md={6}>
                      <FormControl fullWidth>
                        <InputLabel>Intervalo de Coleta</InputLabel>
                        <Select
                          name="scrapingInterval"
                          value={settings.scrapingInterval}
                          label="Intervalo de Coleta"
                          onChange={handleChange}
                          disabled={!settings.scrapingEnabled}
                        >
                          <MenuItem value={6}>A cada 6 horas</MenuItem>
                          <MenuItem value={12}>A cada 12 horas</MenuItem>
                          <MenuItem value={24}>A cada 24 horas</MenuItem>
                        </Select>
                      </FormControl>
                      <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                        Frequência da coleta automática de dados
                      </Typography>
                    </Grid>
                  )}

                  {settings.scrapingMode === 'schedule' && (
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Horário da Coleta"
                        type="time"
                        name="scrapingTime"
                        value={settings.scrapingTime}
                        onChange={handleChange}
                        disabled={!settings.scrapingEnabled}
                        InputLabelProps={{
                          shrink: true,
                        }}
                        inputProps={{
                          step: 300, // 5 min
                        }}
                      />
                      <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                        Horário diário para execução da coleta (formato 24h)
                      </Typography>
                    </Grid>
                  )}

                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.scrapingRetryOnError}
                          onChange={handleChange}
                          name="scrapingRetryOnError"
                          color="primary"
                          disabled={!settings.scrapingEnabled}
                        />
                      }
                      label="Tentar Novamente em Caso de Erro"
                    />
                    <Typography variant="caption" color="text.secondary" display="block">
                      Reexecuta automaticamente a coleta quando ocorrem falhas
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      label="Máximo de Tentativas"
                      type="number"
                      name="scrapingMaxRetries"
                      value={settings.scrapingMaxRetries}
                      onChange={handleChange}
                      disabled={!settings.scrapingEnabled || !settings.scrapingRetryOnError}
                      InputProps={{ inputProps: { min: 1, max: 10 } }}
                    />
                    <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                      Número máximo de tentativas em caso de falha
                    </Typography>
                  </Grid>

                  {/* Status da Última Execução */}
                  <Grid item xs={12}>
                    <Divider sx={{ my: 2 }} />
                    <Typography variant="subtitle1" gutterBottom>
                      Status da Coleta
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">
                          Última Execução:
                        </Typography>
                        <Typography variant="body1">
                          {settings.scrapingLastRun ? new Date(settings.scrapingLastRun).toLocaleString('pt-BR') : 'Nunca executado'}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">
                          Próxima Execução:
                        </Typography>
                        <Typography variant="body1">
                          {settings.scrapingNextRun ? new Date(settings.scrapingNextRun).toLocaleString('pt-BR') : 'Não agendado'}
                        </Typography>
                      </Grid>
                    </Grid>
                    
                    {/* Ações de Controle */}
                    <Box sx={{ mt: 2 }}>
                      <Button
                        variant="contained"
                        color="secondary"
                        onClick={handleForceScrapingExecution}
                        disabled={!settings.scrapingEnabled || loading}
                        sx={{ mr: 2 }}
                      >
                        {loading ? 'Executando...' : 'Executar Agora'}
                      </Button>
                      <Button
                        variant="outlined"
                        color="primary"
                        onClick={handleRefreshScrapingStatus}
                        disabled={loading}
                      >
                        Atualizar Status
                      </Button>
                    </Box>
                  </Grid>
                </Grid>
              </AccordionDetails>
            </Accordion>
          </Grid>

          {/* Backup e Restauração */}
          <Grid item xs={12}>
            <Accordion>
              <AccordionSummary
                expandIcon={<ExpandMoreIcon />}
                aria-controls="panel4a-content"
                id="panel4a-header"
              >
                <Typography variant="h6">Backup e Restauração</Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.autoBackupEnabled}
                          onChange={handleChange}
                          name="autoBackupEnabled"
                          color="primary"
                        />
                      }
                      label="Backup Automático"
                    />
                    <Typography variant="caption" color="text.secondary" display="block">
                      Realiza backups automaticamente no intervalo definido
                    </Typography>
                  </Grid>

                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth sx={{ mt: 2 }}>
                      <InputLabel>Intervalo de Backup</InputLabel>
                      <Select
                        name="autoBackupInterval"
                        value={settings.autoBackupInterval}
                        label="Intervalo de Backup"
                        onChange={handleChange}
                        disabled={!settings.autoBackupEnabled}
                      >
                        <MenuItem value="daily">Diário</MenuItem>
                        <MenuItem value="weekly">Semanal</MenuItem>
                        <MenuItem value="monthly">Mensal</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>

                  <Grid item xs={12} sx={{ mt: 2 }}>
                    <Divider sx={{ mb: 2 }} />
                    <Typography variant="subtitle1" gutterBottom>
                      Ações de Backup
                    </Typography>
                    <Button
                      variant="contained"
                      color="primary"
                      startIcon={<BackupIcon />}
                      onClick={handleCreateBackup}
                      sx={{ mr: 2 }}
                    >
                      Criar Backup Manual
                    </Button>
                    <Button
                      variant="outlined"
                      color="secondary"
                      startIcon={<RestoreIcon />}
                    >
                      Restaurar Backup
                    </Button>
                  </Grid>
                </Grid>
              </AccordionDetails>
            </Accordion>
          </Grid>

          {/* Botão Salvar */}
          <Grid item xs={12} sx={{ mt: 3 }}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              startIcon={<SaveIcon />}
              onClick={handleSaveSettings}
              disabled={loading}
            >
              Salvar Configurações
            </Button>
          </Grid>
        </Grid>
      )}
    </Box>
  );
};

export default SystemSettings;
