import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  CircularProgress,
  Alert,
  TextField,
  InputAdornment,
  IconButton,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Button,
  Divider,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import RefreshIcon from '@mui/icons-material/Refresh';
import FileDownloadIcon from '@mui/icons-material/FileDownload';
import DeleteIcon from '@mui/icons-material/Delete';
import SyncIcon from '@mui/icons-material/Sync';
import { format } from 'date-fns';
import ptBR from 'date-fns/locale/pt-BR';

// Simulação de serviço API para buscar dados brutos de scraping
// Este deve ser substituído pelo serviço real que busca dados do backend
const fetchRawScrapingData = async (page = 0, limit = 10, filters = {}) => {
  try {
    // Esta é uma URL de exemplo - substitua pela rota correta da sua API
    const response = await fetch(`/api/scraping/raw-data?page=${page}&limit=${limit}${
      filters.query ? `&query=${filters.query}` : ''
    }${
      filters.seller ? `&seller=${filters.seller}` : ''
    }${
      filters.dateRange ? `&start_date=${filters.dateRange[0]}&end_date=${filters.dateRange[1]}` : ''
    }`);

    if (!response.ok) {
      throw new Error('Erro ao buscar dados de scraping');
    }

    return await response.json();
  } catch (error) {
    console.error('Erro ao buscar dados brutos:', error);
    // Retornar dados simulados para desenvolvimento
    return {
      data: Array.from({ length: limit }).map((_, index) => ({
        id: (page * limit) + index + 1,
        product_id: `MLB${Math.floor(1000000000 + Math.random() * 9000000000)}`,
        title: `Cartucho HP ${664 + index} ${['Preto', 'Colorido'][index % 2]} Original`,
        price: (50 + Math.random() * 30).toFixed(2),
        seller_name: ['HP Store Oficial', 'Kalunga', 'Magazine Luiza', 'Americanas'][index % 4],
        timestamp: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
        url: `https://mercadolivre.com.br/item/MLB${Math.floor(1000000000 + Math.random() * 9000000000)}`,
        is_original: Math.random() > 0.3,
        stock: Math.floor(Math.random() * 100),
        rating: (3 + Math.random() * 2).toFixed(1),
        review_count: Math.floor(Math.random() * 200)
      })),
      total: 178,
      page,
      limit
    };
  }
};

// Nova função para acionar o scraping
const triggerScraping = async () => {
  try {
    const response = await fetch('/api/scraping/run', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ force: true })
    });

    if (!response.ok) {
      throw new Error(`Erro ao iniciar scraping: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('Erro ao acionar scraping:', error);
    throw error;
  }
};

// Nova função para limpar apenas dados de scraping
const clearScrapingData = async () => {
  try {
    const response = await fetch('/api/settings/clear-scraping-data', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    if (!response.ok) {
      throw new Error(`Erro ao limpar dados de scraping: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('Erro ao limpar dados de scraping:', error);
    throw error;
  }
};

// Função para exportar TODOS os dados para CSV
const exportAllToCSV = async () => {
  try {
    // Configurando indicador de progresso
    const progressDialog = document.createElement('div');
    progressDialog.innerHTML = `
      <div style="position: fixed; top: 0; left: 0; right: 0; bottom: 0; 
                  background: rgba(0,0,0,0.5); z-index: 9999; 
                  display: flex; align-items: center; justify-content: center;">
        <div style="background: white; padding: 20px; border-radius: 8px; text-align: center;">
          <div>Exportando dados...</div>
          <div style="margin-top: 10px;">Por favor, aguarde. Isso pode levar alguns minutos.</div>
        </div>
      </div>
    `;
    document.body.appendChild(progressDialog);

    // Buscando todos os produtos sem paginação
    const response = await fetch('/api/scraping/raw-data?limit=99999');

    if (!response.ok) {
      throw new Error('Erro ao buscar dados para exportação');
    }

    const result = await response.json();
    const allData = result.data || [];

    // Verificando se temos dados para exportar
    if (allData.length === 0) {
      throw new Error('Nenhum dado disponível para exportação');
    }

    // Cabeçalhos
    const headers = Object.keys(allData[0]);

    // Converter dados para linhas de CSV
    const csvRows = [
      headers.join(','), // Cabeçalhos
      ...allData.map(row =>
        headers.map(header => {
          // Garantir que valores com vírgulas estejam entre aspas
          const cell = row[header] === null || row[header] === undefined ? '' : row[header];
          return typeof cell === 'string' && cell.includes(',')
            ? `"${cell}"`
            : cell;
        }).join(',')
      )
    ];

    // Criar blob e link para download
    const csvContent = csvRows.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.setAttribute('href', url);
    link.setAttribute('download', `todos_produtos_${format(new Date(), 'yyyy-MM-dd_HH-mm')}.csv`);
    link.style.visibility = 'hidden';

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    // Remover diálogo de progresso
    document.body.removeChild(progressDialog);

    return allData.length;
  } catch (error) {
    console.error('Erro ao exportar dados:', error);
    throw error;
  }
};

const RawScrapingData = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalItems, setTotalItems] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [sellerFilter, setSellerFilter] = useState('');
  const [isOriginalFilter, setIsOriginalFilter] = useState('');
  const [refreshing, setRefreshing] = useState(false);
  const [exportingAll, setExportingAll] = useState(false);
  const [scrapingActive, setScrapingActive] = useState(false);
  const [openClearDialog, setOpenClearDialog] = useState(false);
  const [operationMessage, setOperationMessage] = useState({ type: '', message: '' });

  // Função para carregar dados
  const loadData = async () => {
    setLoading(true);
    setError(null);

    try {
      const filters = {
        query: searchQuery,
        seller: sellerFilter,
        isOriginal: isOriginalFilter !== '' ? isOriginalFilter : undefined
      };

      const response = await fetchRawScrapingData(page, rowsPerPage, filters);

      setData(response.data);
      setTotalItems(response.total);
    } catch (err) {
      setError('Erro ao carregar dados brutos do scraping: ' + err.message);
      console.error(err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  // Carregar dados quando o componente montar ou quando os filtros/paginação mudarem
  useEffect(() => {
    loadData();
  }, [page, rowsPerPage]);

  // Função para atualizar dados
  const handleRefresh = () => {
    setRefreshing(true);
    loadData();
  };

  // Função para aplicar filtros
  const handleApplyFilters = () => {
    setPage(0); // Resetar para primeira página ao filtrar
    loadData();
  };

  // Função para limpar filtros
  const handleClearFilters = () => {
    setSearchQuery('');
    setSellerFilter('');
    setIsOriginalFilter('');
    setPage(0);
    loadData();
  };

  // Handlers de paginação
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Função para exportar dados atuais da página
  const handleExportCurrentPage = () => {
    if (data && data.length > 0) {
      exportToCSV(data);
    }
  };

  // Nova função para exportar todos os dados
  const handleExportAll = async () => {
    setExportingAll(true);
    try {
      const count = await exportAllToCSV();
      setOperationMessage({
        type: 'success',
        message: `Exportados ${count} registros com sucesso!`
      });
    } catch (err) {
      setOperationMessage({
        type: 'error',
        message: `Erro ao exportar dados: ${err.message}`
      });
    } finally {
      setExportingAll(false);
      // Limpar a mensagem após 5 segundos
      setTimeout(() => setOperationMessage({ type: '', message: '' }), 5000);
    }
  };

  // Nova função para acionar o scraping
  const handleTriggerScraping = async () => {
    setScrapingActive(true);
    setOperationMessage({
      type: 'info',
      message: 'Iniciando o processo de scraping... Isso pode levar alguns minutos.'
    });

    try {
      const result = await triggerScraping();
      setOperationMessage({
        type: 'success',
        message: `Scraping iniciado com sucesso! ${result.message || ''}`
      });

      // Recarregar os dados após 2 segundos para dar tempo do scraping começar
      setTimeout(() => {
        handleRefresh();
      }, 2000);
    } catch (err) {
      setOperationMessage({
        type: 'error',
        message: `Erro ao iniciar scraping: ${err.message}`
      });
    } finally {
      setScrapingActive(false);
      // Limpar a mensagem após 10 segundos
      setTimeout(() => setOperationMessage({ type: '', message: '' }), 10000);
    }
  };

  // Nova função para limpar apenas dados de scraping
  const handleClearScrapingData = async () => {
    setOpenClearDialog(false);

    try {
      setOperationMessage({
        type: 'info',
        message: 'Limpando dados de scraping...'
      });

      const result = await clearScrapingData();

      setOperationMessage({
        type: 'success',
        message: `Dados de scraping limpos com sucesso! ${result.message || ''}`
      });

      // Recarregar os dados após a limpeza
      setTimeout(() => {
        handleRefresh();
      }, 1000);
    } catch (err) {
      setOperationMessage({
        type: 'error',
        message: `Erro ao limpar dados de scraping: ${err.message}`
      });
    }

    // Limpar a mensagem após 5 segundos
    setTimeout(() => setOperationMessage({ type: '', message: '' }), 5000);
  };

  // Formatar data para exibição
  const formatDate = (dateString) => {
    try {
      return format(new Date(dateString), "dd/MM/yyyy HH:mm", { locale: ptBR });
    } catch (e) {
      return dateString;
    }
  };

  // Formatar preço
  const formatCurrency = (value) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  return (
    <Box sx={{ mt: 2 }}>
      <Typography variant="h5" component="h2" gutterBottom>
        Dados Brutos do Scraping
      </Typography>

      <Typography variant="body2" color="text.secondary" paragraph>
        Visualize os dados brutos capturados pelo sistema de scraping do Mercado Livre.
        Utilize os botões de ação para gerenciar o processo de coleta de dados.
      </Typography>

      {/* Ações administrativas */}
      <Paper sx={{ p: 2, mb: 2, bgcolor: 'background.paper' }}>
        <Typography variant="h6" gutterBottom sx={{ mb: 2 }}>
          Ações Administrativas
        </Typography>

        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
          <Button
            variant="contained"
            color="primary"
            startIcon={<SyncIcon />}
            onClick={handleTriggerScraping}
            disabled={scrapingActive}
          >
            {scrapingActive ? 'Executando...' : 'Executar Scraping Agora'}
          </Button>

          <Button
            variant="outlined"
            color="error"
            startIcon={<DeleteIcon />}
            onClick={() => setOpenClearDialog(true)}
          >
            Limpar Dados de Scraping
          </Button>

          <Button
            variant="outlined"
            color="primary"
            startIcon={<FileDownloadIcon />}
            onClick={handleExportAll}
            disabled={exportingAll || loading}
          >
            {exportingAll ? 'Exportando...' : 'Exportar Todos os Dados (CSV)'}
          </Button>
        </Box>

        {/* Mensagem de operação */}
        {operationMessage.message && (
          <Alert
            severity={operationMessage.type}
            sx={{ mt: 2 }}
            onClose={() => setOperationMessage({ type: '', message: '' })}
          >
            {operationMessage.message}
          </Alert>
        )}
      </Paper>

      {/* Filtros */}
      <Paper sx={{ p: 2, mb: 2 }}>
        <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, gap: 2, mb: 2 }}>
          <TextField
            label="Pesquisar"
            placeholder="Pesquisar por título ou código..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            variant="outlined"
            size="small"
            fullWidth
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              ),
            }}
          />

          <FormControl size="small" variant="outlined" sx={{ minWidth: 200 }}>
            <InputLabel>Vendedor</InputLabel>
            <Select
              value={sellerFilter}
              onChange={(e) => setSellerFilter(e.target.value)}
              label="Vendedor"
            >
              <MenuItem value="">Todos</MenuItem>
              <MenuItem value="HP Store Oficial">HP Store Oficial</MenuItem>
              <MenuItem value="Kalunga">Kalunga</MenuItem>
              <MenuItem value="Magazine Luiza">Magazine Luiza</MenuItem>
              <MenuItem value="Americanas">Americanas</MenuItem>
            </Select>
          </FormControl>

          <FormControl size="small" variant="outlined" sx={{ minWidth: 150 }}>
            <InputLabel>Original</InputLabel>
            <Select
              value={isOriginalFilter}
              onChange={(e) => setIsOriginalFilter(e.target.value)}
              label="Original"
            >
              <MenuItem value="">Todos</MenuItem>
              <MenuItem value="true">Original</MenuItem>
              <MenuItem value="false">Não Original</MenuItem>
            </Select>
          </FormControl>
        </Box>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
          <Button variant="outlined" size="small" onClick={handleClearFilters}>
            Limpar Filtros
          </Button>
          <Button
            variant="contained"
            size="small"
            onClick={handleApplyFilters}
          >
            Aplicar Filtros
          </Button>
        </Box>
      </Paper>

      {/* Ações */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="body2" color="text.secondary">
          {totalItems} registros encontrados
        </Typography>

        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button
            variant="outlined"
            size="small"
            startIcon={<RefreshIcon />}
            onClick={handleRefresh}
            disabled={refreshing}
          >
            {refreshing ? 'Atualizando...' : 'Atualizar Dados'}
          </Button>

          <Button
            variant="outlined"
            size="small"
            startIcon={<FileDownloadIcon />}
            onClick={handleExportCurrentPage}
            disabled={loading || data.length === 0}
          >
            Exportar Página Atual
          </Button>
        </Box>
      </Box>

      {/* Tabela de dados */}
      {error ? (
        <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>
      ) : loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <TableContainer component={Paper}>
            <Table sx={{ minWidth: 650 }} size="small">
              <TableHead>
                <TableRow>
                  <TableCell>ID</TableCell>
                  <TableCell>Título</TableCell>
                  <TableCell align="right">Preço</TableCell>
                  <TableCell>Vendedor</TableCell>
                  <TableCell>Original</TableCell>
                  <TableCell align="right">Estoque</TableCell>
                  <TableCell align="right">Avaliação</TableCell>
                  <TableCell>Data</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {data.map((row) => (
                  <TableRow key={row.id} hover>
                    <TableCell component="th" scope="row">
                      {row.product_id}
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" sx={{ maxWidth: 300, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {row.title}
                      </Typography>
                    </TableCell>
                    <TableCell align="right">{formatCurrency(row.price)}</TableCell>
                    <TableCell>{row.seller_name}</TableCell>
                    <TableCell>
                      <Chip
                        label={row.is_original ? "Original" : "Não Original"}
                        color={row.is_original ? "success" : "default"}
                        size="small"
                      />
                    </TableCell>
                    <TableCell align="right">{row.stock}</TableCell>
                    <TableCell align="right">
                      {row.rating} ({row.review_count})
                    </TableCell>
                    <TableCell>{formatDate(row.timestamp)}</TableCell>
                  </TableRow>
                ))}

                {data.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={8} align="center">
                      Nenhum dado encontrado
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <TablePagination
            rowsPerPageOptions={[5, 10, 25, 50]}
            component="div"
            count={totalItems}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
            labelRowsPerPage="Itens por página"
            labelDisplayedRows={({ from, to, count }) => `${from}-${to} de ${count}`}
          />
        </>
      )}

      {/* Diálogo de confirmação para limpar dados de scraping */}
      <Dialog
        open={openClearDialog}
        onClose={() => setOpenClearDialog(false)}
      >
        <DialogTitle>Confirmar Limpeza dos Dados de Scraping</DialogTitle>
        <DialogContent>
          <DialogContentText>
            ATENÇÃO: Esta ação irá apagar APENAS os dados coletados pelo scraping (tabela price_history).
            Os produtos HP cadastrados e configurações do sistema serão mantidos.
            Esta operação NÃO pode ser desfeita. Tem certeza que deseja continuar?
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenClearDialog(false)} color="primary">
            Cancelar
          </Button>
          <Button onClick={handleClearScrapingData} color="error" variant="contained" autoFocus>
            Sim, Limpar Dados de Scraping
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

// Função auxiliar para exportar apenas dados da página atual
const exportToCSV = (data) => {
  if (!data || data.length === 0) return;

  // Cabeçalhos
  const headers = Object.keys(data[0]);

  // Converter dados para linhas de CSV
  const csvRows = [
    headers.join(','), // Cabeçalhos
    ...data.map(row =>
      headers.map(header => {
        // Garantir que valores com vírgulas estejam entre aspas
        const cell = row[header] === null || row[header] === undefined ? '' : row[header];
        return typeof cell === 'string' && cell.includes(',')
          ? `"${cell}"`
          : cell;
      }).join(',')
    )
  ];

  // Criar blob e link para download
  const csvContent = csvRows.join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');

  link.setAttribute('href', url);
  link.setAttribute('download', `dados_pagina_${format(new Date(), 'yyyy-MM-dd_HH-mm')}.csv`);
  link.style.visibility = 'hidden';

  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export default RawScrapingData;
