import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Paper,
  Grid,
  Alert,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Slider,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Checkbox,
  TablePagination,
  IconButton,
  Tooltip,
  Card,
  CardContent,
  Stack,
  Divider,
  Badge,
  Switch,
  FormControlLabel,
  LinearProgress,
  Snackbar
} from '@mui/material';
import {
  Warning,
  Security,
  Settings,
  PlayArrow,
  TrendingDown,
  FilterList,
  Refresh,
  Download,
  Visibility,
  Block,
  CheckCircle,
  Delete,
  History,
  Analytics,
  NotificationImportant,
  AutorenewRounded
} from '@mui/icons-material';
import { get, post, put } from '../../services/api';

const SuspiciousProductsManager = () => {
  const [suspiciousProducts, setSuspiciousProducts] = useState([]);
  const [statistics, setStatistics] = useState({});
  const [threshold, setThreshold] = useState(30);
  const [loading, setLoading] = useState(true);
  const [openSettings, setOpenSettings] = useState(false);
  const [scrapingInProgress, setScrapingInProgress] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  // Estados para filtros e paginação
  const [filters, setFilters] = useState({
    suspicionLevel: '',
    status: '',
    dateRange: 30,
    minPrice: '',
    maxPrice: '',
    seller: ''
  });
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [selectedProducts, setSelectedProducts] = useState([]);
  const [sortBy, setSortBy] = useState('detected_at');
  const [sortOrder, setSortOrder] = useState('desc');

  // Estados para configurações avançadas
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [refreshInterval, setRefreshInterval] = useState(300); // 5 minutos
  const [emailNotifications, setEmailNotifications] = useState(true);

  // Estados para análises
  const [showAnalytics, setShowAnalytics] = useState(false);
  const [analyticsData, setAnalyticsData] = useState({});

  useEffect(() => {
    loadData();
    loadThreshold();
    loadSettings();
  }, [filters, page, rowsPerPage, sortBy, sortOrder]);

  // Auto-refresh
  useEffect(() => {
    let interval;
    if (autoRefresh) {
      interval = setInterval(() => {
        loadData();
      }, refreshInterval * 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [autoRefresh, refreshInterval]);

  const loadData = useCallback(async () => {
    try {
      setLoading(true);

      const queryParams = {
        limit: rowsPerPage,
        offset: page * rowsPerPage,
        days_back: filters.dateRange,
        sort_by: sortBy,
        sort_order: sortOrder,
        ...filters
      };

      // Remover parâmetros vazios
      Object.keys(queryParams).forEach(key => {
        if (queryParams[key] === '' || queryParams[key] == null) {
          delete queryParams[key];
        }
      });

      // Carregar produtos suspeitos
      const productsResponse = await get('/api/suspicious-products/', queryParams);

      if (productsResponse.data && productsResponse.data.success) {
        setSuspiciousProducts(productsResponse.data.data);
      }

      // Carregar estatísticas
      const statsResponse = await get('/api/suspicious-products/statistics', {
        days_back: filters.dateRange
      });

      if (statsResponse.data && statsResponse.data.success) {
        setStatistics(statsResponse.data.data);
      }

      // Carregar dados de análise se necessário
      if (showAnalytics) {
        loadAnalytics();
      }

    } catch (error) {
      console.error('Erro ao carregar dados de produtos suspeitos:', error);
      setError('Erro ao carregar dados dos produtos suspeitos');
    } finally {
      setLoading(false);
    }
  }, [filters, page, rowsPerPage, sortBy, sortOrder, showAnalytics]);

  const loadAnalytics = async () => {
    try {
      const response = await get('/api/suspicious-products/analytics', {
        days_back: filters.dateRange
      });
      if (response.data && response.data.success) {
        setAnalyticsData(response.data.data);
      }
    } catch (error) {
      console.error('Erro ao carregar análises:', error);
    }
  };

  const loadThreshold = async () => {
    try {
      const response = await get('/api/settings/suspicious-threshold');
      if (response.data && response.data.success) {
        setThreshold(response.data.threshold_percentage);
      }
    } catch (error) {
      console.error('Erro ao carregar threshold:', error);
    }
  };

  const loadSettings = async () => {
    try {
      const response = await get('/api/settings/suspicious-products');
      if (response.data && response.data.success) {
        const settings = response.data.data;
        setAutoRefresh(settings.auto_refresh || false);
        setRefreshInterval(settings.refresh_interval || 300);
        setEmailNotifications(settings.email_notifications || true);
      }
    } catch (error) {
      console.error('Erro ao carregar configurações:', error);
    }
  };

  const updateThreshold = async (newThreshold) => {
    try {
      const response = await post(`/api/settings/suspicious-threshold?threshold=${newThreshold}`);
      if (response.success) {
        setThreshold(newThreshold);
        setOpenSettings(false);
        loadData();
        setSuccess(`Threshold atualizado para ${newThreshold}%`);
      }
    } catch (error) {
      console.error('Erro ao atualizar threshold:', error);
      setError('Erro ao atualizar configuração');
    }
  };

  const updateSettings = async (newSettings) => {
    try {
      const response = await post('/api/settings/suspicious-products', newSettings);
      if (response.success) {
        setAutoRefresh(newSettings.auto_refresh);
        setRefreshInterval(newSettings.refresh_interval);
        setEmailNotifications(newSettings.email_notifications);
        setSuccess('Configurações atualizadas com sucesso');
      }
    } catch (error) {
      console.error('Erro ao atualizar configurações:', error);
      setError('Erro ao atualizar configurações');
    }
  };

  const runScraping = async () => {
    try {
      setScrapingInProgress(true);
      const response = await post('/api/suspicious-products/run-scraping');

      if (response.success) {
        setSuccess('Scraping executado com sucesso!');
        setTimeout(() => {
          loadData();
        }, 3000);
      }
    } catch (error) {
      console.error('Erro ao executar scraping:', error);
      setError('Erro ao executar scraping');
    } finally {
      setScrapingInProgress(false);
    }
  };

  const updateProductStatus = async (productId, status) => {
    try {
      const response = await put(`/api/suspicious-products/${productId}/status`, { status });
      if (response.success) {
        setSuccess('Status atualizado com sucesso');
        loadData();
      }
    } catch (error) {
      console.error('Erro ao atualizar status:', error);
      setError('Erro ao atualizar status do produto');
    }
  };

  const bulkUpdateStatus = async (status) => {
    try {
      const response = await post('/api/suspicious-products/bulk-update', {
        product_ids: selectedProducts,
        status
      });
      if (response.success) {
        setSuccess(`${selectedProducts.length} produtos atualizados com sucesso`);
        setSelectedProducts([]);
        loadData();
      }
    } catch (error) {
      console.error('Erro na atualização em lote:', error);
      setError('Erro na atualização em lote');
    }
  };

  const exportData = async () => {
    try {
      const response = await get('/api/suspicious-products/export', filters);
      if (response.data) {
        // Criar e baixar arquivo CSV
        const blob = new Blob([response.data], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `produtos_suspeitos_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
        window.URL.revokeObjectURL(url);
        setSuccess('Dados exportados com sucesso');
      }
    } catch (error) {
      console.error('Erro ao exportar dados:', error);
      setError('Erro ao exportar dados');
    }
  };

  const handleFilterChange = (field, value) => {
    setFilters(prev => ({ ...prev, [field]: value }));
    setPage(0); // Reset para primeira página
  };

  const handleSelectAll = (event) => {
    if (event.target.checked) {
      setSelectedProducts(suspiciousProducts.map(p => p.id));
    } else {
      setSelectedProducts([]);
    }
  };

  const handleSelectProduct = (productId) => {
    setSelectedProducts(prev => {
      if (prev.includes(productId)) {
        return prev.filter(id => id !== productId);
      } else {
        return [...prev, productId];
      }
    });
  };

  const getSuspicionColor = (level) => {
    switch (level) {
      case 'ALTO':
        return 'error';
      case 'MÉDIO':
        return 'warning';
      case 'BAIXO':
        return 'info';
      default:
        return 'default';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'CONFIRMED':
        return 'error';
      case 'FALSE_POSITIVE':
        return 'success';
      case 'INVESTIGATING':
        return 'warning';
      default:
        return 'default';
    }
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    }).format(value);
  };

  if (loading && suspiciousProducts.length === 0) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Cabeçalho com ações */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" component="h2" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Security color="primary" />
          Sistema Anti-Falsificação HP
          {autoRefresh && (
            <Tooltip title="Auto-refresh ativado">
              <AutorenewRounded color="success" />
            </Tooltip>
          )}
        </Typography>

        <Stack direction="row" spacing={1}>
          <Button
            variant="outlined"
            startIcon={<Analytics />}
            onClick={() => setShowAnalytics(!showAnalytics)}
          >
            {showAnalytics ? 'Ocultar' : 'Mostrar'} Análises
          </Button>

          <Button
            variant="outlined"
            startIcon={<Download />}
            onClick={exportData}
          >
            Exportar
          </Button>

          <Button
            variant="outlined"
            startIcon={<Settings />}
            onClick={() => setOpenSettings(true)}
          >
            Configurações
          </Button>

          <Button
            variant="contained"
            startIcon={scrapingInProgress ? <CircularProgress size={20} /> : <PlayArrow />}
            onClick={runScraping}
            disabled={scrapingInProgress}
          >
            {scrapingInProgress ? 'Executando...' : 'Executar Scraping'}
          </Button>
        </Stack>
      </Box>

      {/* Alertas */}
      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {/* Loading bar */}
      {loading && <LinearProgress sx={{ mb: 2 }} />}

      {/* Estatísticas principais */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Badge badgeContent={statistics.new_today || 0} color="error">
                <NotificationImportant color="error" sx={{ fontSize: 40 }} />
              </Badge>
              <Typography variant="h4" color="error.main" sx={{ mt: 1 }}>
                {statistics.total_suspicious || 0}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Produtos Suspeitos
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Warning color="warning" sx={{ fontSize: 40 }} />
              <Typography variant="h4" color="warning.main" sx={{ mt: 1 }}>
                {statistics.by_suspicion_level?.ALTO || 0}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Alto Risco
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Security color="info" sx={{ fontSize: 40 }} />
              <Typography variant="h4" color="info.main" sx={{ mt: 1 }}>
                {threshold}%
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Threshold Atual
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={3}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <CheckCircle color="success" sx={{ fontSize: 40 }} />
              <Typography variant="h4" color="success.main" sx={{ mt: 1 }}>
                {statistics.by_status?.CONFIRMED || 0}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Confirmados
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Análises avançadas */}
      {showAnalytics && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" sx={{ mb: 2 }}>
            Análises Avançadas
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Typography variant="subtitle2" gutterBottom>
                Sellers com mais produtos suspeitos
              </Typography>
              {analyticsData.top_suspicious_sellers?.map((seller, index) => (
                <Box key={seller.name} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                  <Typography variant="body2">{seller.name}</Typography>
                  <Chip label={seller.count} size="small" color="error" />
                </Box>
              ))}
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="subtitle2" gutterBottom>
                Tendência de detecções (últimos 7 dias)
              </Typography>
              {analyticsData.detection_trend?.map((day, index) => (
                <Box key={day.date} sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                  <Typography variant="body2">{day.date}</Typography>
                  <Chip label={day.count} size="small" />
                </Box>
              ))}
            </Grid>
          </Grid>
        </Paper>
      )}

      {/* Filtros */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" sx={{ mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
          <FilterList />
          Filtros
        </Typography>

        <Grid container spacing={2}>
          <Grid item xs={12} sm={6} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>Nível de Suspeição</InputLabel>
              <Select
                value={filters.suspicionLevel}
                onChange={(e) => handleFilterChange('suspicionLevel', e.target.value)}
                label="Nível de Suspeição"
              >
                <MenuItem value="">Todos</MenuItem>
                <MenuItem value="ALTO">Alto</MenuItem>
                <MenuItem value="MÉDIO">Médio</MenuItem>
                <MenuItem value="BAIXO">Baixo</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>Status</InputLabel>
              <Select
                value={filters.status}
                onChange={(e) => handleFilterChange('status', e.target.value)}
                label="Status"
              >
                <MenuItem value="">Todos</MenuItem>
                <MenuItem value="PENDING">Pendente</MenuItem>
                <MenuItem value="INVESTIGATING">Investigando</MenuItem>
                <MenuItem value="CONFIRMED">Confirmado</MenuItem>
                <MenuItem value="FALSE_POSITIVE">Falso Positivo</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>Período</InputLabel>
              <Select
                value={filters.dateRange}
                onChange={(e) => handleFilterChange('dateRange', e.target.value)}
                label="Período"
              >
                <MenuItem value={7}>Últimos 7 dias</MenuItem>
                <MenuItem value={15}>Últimos 15 dias</MenuItem>
                <MenuItem value={30}>Últimos 30 dias</MenuItem>
                <MenuItem value={90}>Últimos 90 dias</MenuItem>
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <TextField
              fullWidth
              size="small"
              label="Preço Mínimo"
              type="number"
              value={filters.minPrice}
              onChange={(e) => handleFilterChange('minPrice', e.target.value)}
            />
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <TextField
              fullWidth
              size="small"
              label="Preço Máximo"
              type="number"
              value={filters.maxPrice}
              onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
            />
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <Button
              fullWidth
              variant="outlined"
              startIcon={<Refresh />}
              onClick={() => {
                setFilters({
                  suspicionLevel: '',
                  status: '',
                  dateRange: 30,
                  minPrice: '',
                  maxPrice: '',
                  seller: ''
                });
                setPage(0);
              }}
            >
              Limpar
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {/* Ações em lote */}
      {selectedProducts.length > 0 && (
        <Paper sx={{ p: 2, mb: 3, backgroundColor: 'action.hover' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <Typography variant="body1">
              {selectedProducts.length} produto(s) selecionado(s)
            </Typography>
            <Stack direction="row" spacing={1}>
              <Button
                size="small"
                variant="contained"
                color="error"
                onClick={() => bulkUpdateStatus('CONFIRMED')}
              >
                Marcar como Confirmado
              </Button>
              <Button
                size="small"
                variant="contained"
                color="success"
                onClick={() => bulkUpdateStatus('FALSE_POSITIVE')}
              >
                Marcar como Falso Positivo
              </Button>
              <Button
                size="small"
                variant="contained"
                color="warning"
                onClick={() => bulkUpdateStatus('INVESTIGATING')}
              >
                Marcar como Investigando
              </Button>
            </Stack>
          </Box>
        </Paper>
      )}

      {/* Lista de Produtos Suspeitos */}
      <Paper sx={{ p: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Warning color="warning" />
            Produtos Suspeitos
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Total: {statistics.total_suspicious || 0} produtos
          </Typography>
        </Box>

        {suspiciousProducts.length === 0 ? (
          <Alert severity="info">
            Nenhum produto suspeito encontrado com os filtros aplicados.
          </Alert>
        ) : (
          <>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox">
                      <Checkbox
                        indeterminate={selectedProducts.length > 0 && selectedProducts.length < suspiciousProducts.length}
                        checked={suspiciousProducts.length > 0 && selectedProducts.length === suspiciousProducts.length}
                        onChange={handleSelectAll}
                      />
                    </TableCell>
                    <TableCell>Produto</TableCell>
                    <TableCell>Vendedor</TableCell>
                    <TableCell>Preço</TableCell>
                    <TableCell>Referência</TableCell>
                    <TableCell>Diferença</TableCell>
                    <TableCell>Risco</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Detectado</TableCell>
                    <TableCell>Ações</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {suspiciousProducts.map((product) => (
                    <TableRow key={product.id} selected={selectedProducts.includes(product.id)}>
                      <TableCell padding="checkbox">
                        <Checkbox
                          checked={selectedProducts.includes(product.id)}
                          onChange={() => handleSelectProduct(product.id)}
                        />
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" sx={{ maxWidth: 200 }}>
                          {product.title}
                        </Typography>
                        {product.ml_id && (
                          <Typography variant="caption" color="text.secondary">
                            ML: {product.ml_id}
                          </Typography>
                        )}
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2">{product.seller_name}</Typography>
                        {product.seller_reputation && (
                          <Chip
                            label={product.seller_reputation}
                            size="small"
                            color="default"
                            sx={{ mt: 0.5 }}
                          />
                        )}
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="error.main" fontWeight="bold">
                          {formatCurrency(product.price)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="text.secondary">
                          {formatCurrency(product.reference_price)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <TrendingDown color="error" fontSize="small" />
                          <Typography variant="body2" color="error.main" fontWeight="bold">
                            -{product.price_difference_percent}%
                          </Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={product.suspicion_level}
                          color={getSuspicionColor(product.suspicion_level)}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={product.status || 'PENDING'}
                          color={getStatusColor(product.status)}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="text.secondary">
                          {new Date(product.detected_at).toLocaleDateString('pt-BR')}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Stack direction="row" spacing={0.5}>
                          <Tooltip title="Ver detalhes">
                            <IconButton size="small" onClick={() => window.open(product.ml_url, '_blank')}>
                              <Visibility />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Marcar como confirmado">
                            <IconButton
                              size="small"
                              color="error"
                              onClick={() => updateProductStatus(product.id, 'CONFIRMED')}
                            >
                              <Block />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Marcar como falso positivo">
                            <IconButton
                              size="small"
                              color="success"
                              onClick={() => updateProductStatus(product.id, 'FALSE_POSITIVE')}
                            >
                              <CheckCircle />
                            </IconButton>
                          </Tooltip>
                        </Stack>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <TablePagination
              component="div"
              count={statistics.total_suspicious || 0}
              page={page}
              onPageChange={(_, newPage) => setPage(newPage)}
              rowsPerPage={rowsPerPage}
              onRowsPerPageChange={(e) => {
                setRowsPerPage(parseInt(e.target.value, 10));
                setPage(0);
              }}
              rowsPerPageOptions={[5, 10, 25, 50]}
              labelRowsPerPage="Produtos por página:"
              labelDisplayedRows={({ from, to, count }) => `${from}-${to} de ${count}`}
            />
          </>
        )}
      </Paper>

      {/* Dialog de Configurações Avançadas */}
      <Dialog open={openSettings} onClose={() => setOpenSettings(false)} maxWidth="md" fullWidth>
        <DialogTitle>Configurações do Sistema Anti-Falsificação</DialogTitle>
        <DialogContent>
          <Box sx={{ pt: 2 }}>
            {/* Configuração de Threshold */}
            <Typography variant="h6" gutterBottom>
              Threshold de Detecção
            </Typography>
            <Typography gutterBottom>
              Threshold Atual: {threshold}%
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
              Produtos com preços {threshold}% ou mais abaixo do valor de referência serão considerados suspeitos.
            </Typography>

            <Slider
              value={threshold}
              onChange={(_, value) => setThreshold(value)}
              min={5}
              max={90}
              step={5}
              marks={[
                { value: 10, label: '10%' },
                { value: 30, label: '30%' },
                { value: 50, label: '50%' },
                { value: 70, label: '70%' }
              ]}
              valueLabelDisplay="auto"
            />

            <Divider sx={{ my: 3 }} />

            {/* Configurações de Auto-refresh */}
            <Typography variant="h6" gutterBottom>
              Atualização Automática
            </Typography>

            <FormControlLabel
              control={
                <Switch
                  checked={autoRefresh}
                  onChange={(e) => setAutoRefresh(e.target.checked)}
                />
              }
              label="Ativar atualização automática"
            />

            {autoRefresh && (
              <Box sx={{ mt: 2 }}>
                <Typography gutterBottom>
                  Intervalo de atualização: {refreshInterval} segundos
                </Typography>
                <Slider
                  value={refreshInterval}
                  onChange={(_, value) => setRefreshInterval(value)}
                  min={60}
                  max={3600}
                  step={60}
                  marks={[
                    { value: 60, label: '1min' },
                    { value: 300, label: '5min' },
                    { value: 900, label: '15min' },
                    { value: 1800, label: '30min' },
                    { value: 3600, label: '1h' }
                  ]}
                  valueLabelDisplay="auto"
                />
              </Box>
            )}

            <Divider sx={{ my: 3 }} />

            {/* Configurações de Notificações */}
            <Typography variant="h6" gutterBottom>
              Notificações
            </Typography>

            <FormControlLabel
              control={
                <Switch
                  checked={emailNotifications}
                  onChange={(e) => setEmailNotifications(e.target.checked)}
                />
              }
              label="Receber notificações por e-mail"
            />

            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                <strong>Recomendado:</strong> 30% para cartuchos HP originais.
                Valores menores podem gerar muitos falsos positivos.
              </Typography>
            </Alert>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenSettings(false)}>
            Cancelar
          </Button>
          <Button
            onClick={() => {
              updateThreshold(threshold);
              updateSettings({
                auto_refresh: autoRefresh,
                refresh_interval: refreshInterval,
                email_notifications: emailNotifications
              });
            }}
            variant="contained"
          >
            Salvar Configurações
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar para mensagens de sucesso */}
      <Snackbar
        open={!!success}
        autoHideDuration={6000}
        onClose={() => setSuccess(null)}
        message={success}
      />
    </Box>
  );
};

export default SuspiciousProductsManager;
