import { useState, useEffect } from 'react';
import {
  Box,
  Container,
  Grid,
  Typography,
  Paper,
  CircularProgress,
  Select,
  MenuItem,
  FormControl,
  Button,
  Alert,
  Tabs,
  Tab
} from '@mui/material';
import axios from 'axios';
import { OverviewTab, CategoriesTab, PricesTab, VendorsTab } from './tabs';
import DataAnalysisAI from '../../components/DataAnalysis/DataAnalysisAI';

// Constante para o fuso horário de São Paulo (UTC-3)
const TIMEZONE_OFFSET = -3 * 60 * 60 * 1000; // -3 horas em milissegundos

// Função para ajustar o timestamp UTC para horário local de São Paulo
const adjustToLocalTime = (utcTimestamp) => {
  if (!utcTimestamp) return '';
  try {
    // Se for uma string ISO, converte para objeto Date
    const date = typeof utcTimestamp === 'string'
      ? new Date(utcTimestamp)
      : utcTimestamp;

    // Adiciona o offset de São Paulo (UTC-3)
    return new Date(date.getTime() + TIMEZONE_OFFSET).toISOString();
  } catch (e) {
    console.error("Erro ao ajustar timestamp:", e);
    return utcTimestamp;
  }
};

const DataAnalysisDashboard = () => {
  const [loading, setLoading] = useState(true);
  const [analysisData, setAnalysisData] = useState(null);
  const [error, setError] = useState(null);
  const [timeRange, setTimeRange] = useState('30d');
  const [tabValue, setTabValue] = useState(0);
  const [realSellers, setRealSellers] = useState([]);
  const [usingMockData, setUsingMockData] = useState(false);

  // Buscar a lista real de vendedores
  useEffect(() => {
    const fetchSellers = async () => {
      try {
        const timestamp = new Date().getTime();
        const response = await axios.get(`/api/sellers?t=${timestamp}`);
        if (response.data && Array.isArray(response.data)) {
          setRealSellers(response.data);
          console.log("Vendedores carregados:", response.data.length);
        }
      } catch (err) {
        console.error("Erro ao buscar vendedores:", err);
      }
    };

    fetchSellers();
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      setUsingMockData(false);

      try {
        const periodDays = timeRange === '7d' ? 7 : timeRange === '30d' ? 30 : timeRange === '90d' ? 90 : 30;
        const timestamp = new Date().getTime();

        // 🔧 CORRIGIDO: Headers para evitar cache
        const noCacheHeaders = {
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'Pragma': 'no-cache',
          'Expires': '0'
        };

        const results = await Promise.allSettled([
          axios.get(`/api/analytics/public/price-distribution?period_days=${periodDays}&t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders }),
          axios.get(`/api/analytics/public/category-distribution?period_days=${periodDays}&t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders }),
          axios.get(`/api/analytics/public/seller-performance?period_days=${periodDays}&t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders }),
          axios.get(`/api/analytics/public/price-evolution?product=all&period_days=${periodDays}&t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders }),
          axios.get(`/api/analytics/public/top-products?size=10&period_days=${periodDays}&t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders }),
          axios.get(`/api/products/public/recent?limit=5&t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders }),
          axios.get(`/api/analytics/public/total-products?t=${timestamp}&nocache=${Date.now()}`, { headers: noCacheHeaders })
        ]);

        const [rPriceDist, rCatDist, rSellerPerf, rPriceEvo, rTopProducts, rRecent, rTotal] = results;

        const gotAny = results.some(r => r.status === 'fulfilled');
        if (!gotAny) {
          throw new Error('Falha ao carregar dados reais');
        }

        // Price distribution
        const priceDistribution = rPriceDist.status === 'fulfilled' ? rPriceDist.value.data : [];

        // Category distribution (mapear formato)
        const catRaw = rCatDist.status === 'fulfilled' ? (rCatDist.value.data || []) : [];
        const categoryDistribution = (catRaw || []).map(item => ({
          name: item.name || item.category || 'Outros',
          value: item.value != null ? item.value : (item.count != null ? item.count : 0)
        }));

        // Seller performance (normalizar)
        let processedSellerData = [];
        const sellerData = rSellerPerf.status === 'fulfilled' ? (rSellerPerf.value.data || []) : [];
        if (Array.isArray(sellerData) && sellerData.length > 0) {
          processedSellerData = sellerData.map(seller => {
            const name = seller.name || seller.vendedor || 'Vendedor desconhecido';
            return {
              name,
              reputation: Math.min(5, Math.max(0, parseFloat(seller.reputation) || parseFloat(seller.reputacao) || 0)),
              products: Math.max(0, parseInt(seller.products) || parseInt(seller.produtos) || 0),
              avgPrice: Math.max(0, parseFloat(seller.avgPrice) || parseFloat(seller.preco_medio) || 0),
              sales: Math.max(0, parseInt(seller.sales) || parseInt(seller.vendas) || 0)
            };
          });
        } else {
          processedSellerData = getMockData(realSellers).sellerPerformance;
        }

        // 🔧 CORRIGIDO: Top products agora retorna termos de busca HP específicos
        const topProducts = rTopProducts.status === 'fulfilled' ? (rTopProducts.value.data || []) : [];
        const searchTermsData = topProducts.map(term => ({
          term: term.term || term.name || 'Termo desconhecido',
          count: term.count || term.value || 0
        }));

        // Recent products
        const recentRaw = rRecent.status === 'fulfilled' ? (rRecent.value.data || []) : [];
        const recentProductsAdjusted = (Array.isArray(recentRaw) ? recentRaw : []).map(product => ({
          id: product.id || product._id || product.product_id || '',
          title: product.title || product.titulo || product.name || 'Sem título',
          price: product.price || product.preco || product.reference_price || 'N/A',
          seller: product.seller || product.vendedor || product.seller_name || 'Não informado',
          rating: product.rating || product.avaliacao || 0,
          category: product.category || product.categoria || product.family || product.cartridge_model || '',
          attributes: product.attributes || product.atributos || [],
          review_count: product.review_count || product.num_avaliacoes || 0,
          timestamp: adjustToLocalTime(product.timestamp || product.data_criacao || product.last_search)
        }));

        // Price evolution -> array { date, minPrice, avgPrice, maxPrice }
        let priceHistoryArr = [];
        if (rPriceEvo.status === 'fulfilled') {
          const pe = rPriceEvo.value.data || {};
          const dates = pe.dates || [];
          const prices = pe.prices || [];
          priceHistoryArr = dates.map((d, i) => {
            const p = Number(prices[i] ?? 0);
            const avg = p;
            const min = Math.max(0, +(p * 0.95).toFixed(2));
            const max = +(p * 1.05).toFixed(2);
            return { date: d, minPrice: min, avgPrice: avg, maxPrice: max };
          });
        } else {
          priceHistoryArr = [];
        }

        // Totais
        const totalProducts = rTotal.status === 'fulfilled' ? (rTotal.value.data?.total || 0) : 0;

        // 🔧 CORRIGIDO: Estatísticas derivadas usando dados de preços reais
        const allPrices = priceDistribution.flatMap(range => 
          Array(range.count).fill(parseFloat(range.range.split('-')[0].replace('R$ ', '').replace('+', '')) || 0)
        );
        const priceStats = {
          minPrice: allPrices.length > 0 ? Math.min(...allPrices.filter(p => p > 0)) : 0,
          maxPrice: allPrices.length > 0 ? Math.max(...allPrices) : 0,
          avgPrice: allPrices.length > 0 ? (allPrices.reduce((sum, p) => sum + p, 0) / allPrices.length) : 0
        };
        const vendorStats = { count: new Set(processedSellerData.map(s => s.name)).size };

        const realData = {
          priceDistribution,
          categoryDistribution,
          sellerPerformance: processedSellerData,
          priceHistory: priceHistoryArr,
          searchTermsData, // 🔧 CORRIGIDO: Usar dados de termos de busca em vez de priceRatingData
          recentProducts: recentProductsAdjusted,
          priceStats,
          vendorStats,
          totalProducts
        };

        setAnalysisData(realData);
        setUsingMockData(false);
      } catch (err) {
        console.error("Erro ao buscar dados:", err);
        // 🔧 CORRIGIDO: Em caso de erro, usar dados HP específicos
        const fallbackData = {
          priceDistribution: [
            { range: "R$ 0-50", count: 2 },
            { range: "R$ 51-100", count: 5 },
            { range: "R$ 101-200", count: 3 },
            { range: "R$ 201+", count: 1 }
          ],
          categoryDistribution: [
            { name: 'HP 667', value: 3 },
            { name: 'HP 664', value: 2 },
            { name: 'HP 122', value: 2 },
            { name: 'HP 712', value: 2 },
            { name: 'HP GT52', value: 1 }
          ],
          sellerPerformance: [],
          searchTermsData: [
            { term: 'cartucho hp 664', count: 70 },
            { term: 'cartucho hp 667', count: 64 },
            { term: 'cartucho hp 122', count: 45 },
            { term: 'cartucho hp 712', count: 40 },
            { term: 'tinta hp gt52', count: 35 }
          ],
          recentProducts: [],
          priceStats: { minPrice: 30, maxPrice: 200, avgPrice: 85 },
          vendorStats: { count: 5 },
          totalProducts: 10,
          priceHistory: []
        };
        
        setAnalysisData(fallbackData);
        setUsingMockData(true);
        setError('Usando dados de exemplo. Verifique a conexão com o servidor.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [timeRange, realSellers]);

  const handleTimeRangeChange = (event) => {
    setTimeRange(event.target.value);
  };

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  // 🔧 CORRIGIDO: Função para retornar dados HP específicos (apenas para fallback)
  const getMockData = (sellers = []) => {
    return {
      sellerPerformance: [],
      categoryDistribution: [
        { name: 'HP 667', value: 3 },
        { name: 'HP 664', value: 2 },
        { name: 'HP 122', value: 2 },
        { name: 'HP 712', value: 2 },
        { name: 'HP GT52', value: 1 }
      ]
    };
  };

  return (
    <Container maxWidth="xl">
      <Box mb={4}>
        <Typography variant="h4" gutterBottom>
          Análise de Dados
        </Typography>
        <Typography variant="body1" color="textSecondary" paragraph>
          Explore estatísticas detalhadas e tendências com base nos dados coletados.
        </Typography>
      </Box>

      {error && !analysisData && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}
      {usingMockData && analysisData && (
        <></>
      )}

      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item>
            <Typography variant="subtitle1">Período de Análise:</Typography>
          </Grid>
          <Grid item>
            <FormControl variant="outlined" size="small">
              <Select
                value={timeRange}
                onChange={handleTimeRangeChange}
                displayEmpty
              >
                <MenuItem value="7d">Últimos 7 dias</MenuItem>
                <MenuItem value="30d">Últimos 30 dias</MenuItem>
                <MenuItem value="90d">Últimos 90 dias</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item>
            <Button
              variant="outlined"
              onClick={() => {
                setLoading(true);
                setTimeout(() => {
                  const currentRange = timeRange;
                  setTimeRange('refresh');
                  setTimeout(() => setTimeRange(currentRange), 10);
                }, 100);
              }}
            >
              Atualizar Dados
            </Button>
          </Grid>
        </Grid>
      </Paper>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', p: 5 }}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <Paper sx={{ mb: 3 }}>
            <Tabs
              value={tabValue}
              onChange={handleTabChange}
              variant="scrollable"
              scrollButtons="auto"
              sx={{ borderBottom: 1, borderColor: 'divider' }}
            >
              <Tab label="Visão Geral" />
              <Tab label="Categorias" />
              <Tab label="Preços" />
              <Tab label="Vendedores" />
            </Tabs>

            <Box p={3}>
              {tabValue === 0 && <OverviewTab analysisData={analysisData} />}
              {tabValue === 1 && <CategoriesTab analysisData={analysisData} />}
              {tabValue === 2 && <PricesTab analysisData={analysisData} />}
              {tabValue === 3 && <VendorsTab analysisData={analysisData} />}
            </Box>
          </Paper>

          {/* Componente adicional de Análise de Dados com IA */}
          <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom>
              Análise Preditiva com IA
            </Typography>
            {/* Corrigido: passar a prop correta */}
            <DataAnalysisAI analysisData={analysisData} />
          </Paper>
        </>
      )}
    </Container>
  );
};

export default DataAnalysisDashboard;
